    // ── STIMULI-SIGNOFF.12: the `@quantified_separator` directive ──

    /// A minimal line-oriented-ish synthetic grammar: `file := item+`,
    /// `item := /x/`. NOT svpp — the generator is named "test" — proving the
    /// separator capability is grammar-declared, never grammar-name-gated.
    fn quantified_separator_fixture() -> (HashMap<String, ASTNode>, Vec<String>) {
        let mut grammar_tree = HashMap::new();
        grammar_tree.insert(
            "file".to_string(),
            ASTNode::Quantified {
                element: Box::new(token("rule_reference", "item")),
                quantifier: "+".to_string(),
            },
        );
        grammar_tree.insert("item".to_string(), token("regex", "x"));
        (grammar_tree, vec!["file".to_string(), "item".to_string()])
    }

    fn quantified_separator_annotations(rule: &str, payload_text: &str) -> Annotations {
        let mut annotations = Annotations::default();
        annotations.semantic_annotations.insert(
            rule.to_string(),
            vec![SemanticAnnotation::Named {
                name: "quantified_separator".to_string(),
                ast: UnifiedSemanticAST::from_named_payload("quantified_separator", payload_text),
            }],
        );
        annotations
    }

    fn generator_with_annotations<'a>(
        grammar_tree: &'a HashMap<String, ASTNode>,
        rule_order: &'a [String],
        annotations: Option<&'a Annotations>,
        seed: u64,
    ) -> StimuliGenerator<'a> {
        StimuliGenerator::new(
            "test".to_string(),
            grammar_tree,
            rule_order,
            annotations,
            StimuliConfig {
                seed: Some(seed),
                max_depth: 8,
                max_repeat: 4,
                max_rule_visits: 4,
                target_pending_frontier_extra_stagnation: 8,
                target_generation_timeout_ms: 0,
                target_helper_generation_timeout_ms: 1000,
                recovery_mode: RecoveryStimuliMode::Baseline,
                mutation_mode: StimuliMutationMode::Baseline,
                constraint_profile: StimuliConstraintProfile::Baseline,
                negative_profile: StimuliNegativeProfile::Baseline,
                enforce_word_boundary_spacing: false,
                trace_verbosity: TraceVerbosity::None,
                reach_uncovered_recursive_branches: false,
            },
        )
    }

    #[test]
    fn quantified_separator_directive_separates_stacked_renderings_for_any_grammar() {
        let (grammar_tree, rule_order) = quantified_separator_fixture();
        let annotations = quantified_separator_annotations("item", r#"";""#);
        let mut saw_multi_item_sample = false;
        for seed in [0u64, 7, 42, 99] {
            let mut generator =
                generator_with_annotations(&grammar_tree, &rule_order, Some(&annotations), seed);
            for sample in generator
                .generate_many(8, Some("file"))
                .expect("separator-annotated generation should succeed")
            {
                assert!(
                    sample.split(';').all(|part| part == "x"),
                    "stacked items must be ';'-separated x renderings (seed {seed}): {sample:?}"
                );
                saw_multi_item_sample |= sample.contains(';');
            }
        }
        assert!(
            saw_multi_item_sample,
            "at least one sample must stack >=2 items so the separator is exercised"
        );
    }

    /// STIMULI-SIGNOFF.13.4: synthetic declare-then-use grammar for the
    /// `@gen_emit_fact` / `@gen_predicate` render-time value-draw tests —
    /// `file := decl use_site`; the producer `dname` registers its render as a
    /// `cap_name` fact; the consumer `uname` draws a live `cap_name` name.
    fn gen_store_draw_fixture() -> (HashMap<String, ASTNode>, Vec<String>) {
        let mut g = HashMap::new();
        g.insert(
            "file".to_string(),
            ASTNode::Sequence {
                elements: vec![rule_ref("decl"), rule_ref("use_site")],
            },
        );
        g.insert(
            "decl".to_string(),
            ASTNode::Sequence {
                elements: vec![
                    token("quoted_string", "d:"),
                    rule_ref("dname"),
                    token("quoted_string", ";"),
                ],
            },
        );
        g.insert("dname".to_string(), token("regex", "[a-u][a-u]"));
        g.insert(
            "use_site".to_string(),
            ASTNode::Sequence {
                elements: vec![
                    token("quoted_string", "u:"),
                    rule_ref("uname"),
                    token("quoted_string", ";"),
                ],
            },
        );
        g.insert("uname".to_string(), token("regex", "[a-u][a-u]"));
        (
            g,
            vec![
                "file".to_string(),
                "decl".to_string(),
                "dname".to_string(),
                "use_site".to_string(),
                "uname".to_string(),
            ],
        )
    }

    fn gen_store_annotation(rule: &str, directive: &str, payload: &str) -> (String, SemanticAnnotation) {
        (
            rule.to_string(),
            SemanticAnnotation::Named {
                name: directive.to_string(),
                ast: UnifiedSemanticAST::from_named_payload(directive, payload),
            },
        )
    }

    fn gen_store_annotations(entries: &[(String, SemanticAnnotation)]) -> Annotations {
        let mut annotations = Annotations::default();
        for (rule, annotation) in entries {
            annotations
                .semantic_annotations
                .entry(rule.clone())
                .or_default()
                .push(annotation.clone());
        }
        annotations
    }

    #[test]
    fn gen_value_name_draw_renders_a_live_stored_name_and_is_deterministic() {
        let (grammar_tree, rule_order) = gen_store_draw_fixture();
        let annotations = gen_store_annotations(&[
            gen_store_annotation("dname", "gen_emit_fact", "{ kind: cap_name, name: $dname }"),
            gen_store_annotation(
                "uname",
                "gen_predicate",
                "{ name: has_fact, args: [cap_name, $text], phase: post }",
            ),
        ]);
        for seed in [0u64, 7, 42, 99] {
            let mut generator =
                generator_with_annotations(&grammar_tree, &rule_order, Some(&annotations), seed);
            let samples = generator
                .generate_many(8, Some("file"))
                .expect("draw-gated generation should succeed");
            for sample in &samples {
                // Shape: d:<declared>;u:<used>; — the used name must BE the declared name.
                let rest = sample
                    .strip_prefix("d:")
                    .unwrap_or_else(|| panic!("unexpected sample shape (seed {seed}): {sample:?}"));
                let (declared, rest) = rest
                    .split_once(";u:")
                    .unwrap_or_else(|| panic!("unexpected sample shape (seed {seed}): {sample:?}"));
                let used = rest
                    .strip_suffix(';')
                    .unwrap_or_else(|| panic!("unexpected sample shape (seed {seed}): {sample:?}"));
                assert_eq!(
                    used, declared,
                    "the consumer must render the LIVE declared name (seed {seed}): {sample:?}"
                );
            }
            // Determinism: the same seed reproduces the exact sample vector.
            let mut replay =
                generator_with_annotations(&grammar_tree, &rule_order, Some(&annotations), seed);
            let replayed = replay
                .generate_many(8, Some("file"))
                .expect("replay generation should succeed");
            assert_eq!(samples, replayed, "same-seed draws must be byte-identical");
        }
    }

    #[test]
    fn gen_value_index_draw_stays_within_the_live_count() {
        // file := decl decl use_site ; decl := "(" ")" emits one `grp` fact;
        // inum draws an index in 1..=count(grp) — its regex body [5-9] can NEVER
        // render, so any 1/2 render proves the draw replaced the body.
        let mut g = HashMap::new();
        g.insert(
            "file".to_string(),
            ASTNode::Sequence {
                elements: vec![rule_ref("decl"), rule_ref("decl"), rule_ref("use_site")],
            },
        );
        g.insert(
            "decl".to_string(),
            ASTNode::Sequence {
                elements: vec![token("quoted_string", "("), token("quoted_string", ")")],
            },
        );
        g.insert(
            "use_site".to_string(),
            ASTNode::Sequence {
                elements: vec![token("quoted_string", "#"), rule_ref("inum")],
            },
        );
        g.insert("inum".to_string(), token("regex", "[5-9]"));
        let rule_order = vec![
            "file".to_string(),
            "decl".to_string(),
            "use_site".to_string(),
            "inum".to_string(),
        ];
        let annotations = gen_store_annotations(&[
            gen_store_annotation("decl", "gen_emit_fact", "{ kind: grp, name: g }"),
            gen_store_annotation(
                "inum",
                "gen_predicate",
                "{ name: fact_count_at_least, args: [grp, $value], phase: post }",
            ),
        ]);
        let mut seen: std::collections::HashSet<String> = std::collections::HashSet::new();
        for seed in [0u64, 7, 42, 99] {
            let mut generator =
                generator_with_annotations(&g, &rule_order, Some(&annotations), seed);
            for sample in generator
                .generate_many(8, Some("file"))
                .expect("index-draw generation should succeed")
            {
                let index = sample
                    .strip_prefix("()()#")
                    .unwrap_or_else(|| panic!("unexpected sample shape (seed {seed}): {sample:?}"));
                assert!(
                    index == "1" || index == "2",
                    "the drawn index must stay within the live count 2 (seed {seed}): {sample:?}"
                );
                seen.insert(index.to_string());
            }
        }
        assert_eq!(
            seen.len(),
            2,
            "both live indices must be drawn across seeds/samples: {seen:?}"
        );
    }

    #[test]
    fn gen_value_draw_with_an_empty_pool_backtracks_to_a_sibling_branch() {
        // NO producer exists, so the has_fact-gated branch is ungeneratable —
        // the count-prune backtracks it and the Or falls to the fallback.
        let mut g = HashMap::new();
        g.insert(
            "file".to_string(),
            ASTNode::Or {
                alternatives: vec![
                    ASTNode::Sequence {
                        elements: vec![
                            token("quoted_string", "<"),
                            rule_ref("uname"),
                            token("quoted_string", ">"),
                        ],
                    },
                    token("quoted_string", "fallback"),
                ],
            },
        );
        g.insert("uname".to_string(), token("regex", "[a-u][a-u]"));
        let rule_order = vec!["file".to_string(), "uname".to_string()];
        let annotations = gen_store_annotations(&[gen_store_annotation(
            "uname",
            "gen_predicate",
            "{ name: has_fact, args: [cap_name, $text], phase: post }",
        )]);
        for seed in [0u64, 7, 42, 99] {
            let mut generator =
                generator_with_annotations(&g, &rule_order, Some(&annotations), seed);
            for sample in generator
                .generate_many(8, Some("file"))
                .expect("generation should fall back to the ungated branch")
            {
                assert_eq!(
                    sample, "fallback",
                    "zero live facts must backtrack the draw-gated branch (seed {seed})"
                );
            }
        }
    }

    #[test]
    fn gen_store_directive_fold_registers_emit_prune_prelude_and_draw_maps() {
        let annotations = gen_store_annotations(&[
            gen_store_annotation("dname", "gen_emit_fact", "{ kind: cap_name, name: $dname }"),
            gen_store_annotation(
                "uname",
                "gen_predicate",
                "{ name: has_fact, args: [cap_name, $text], phase: post }",
            ),
            gen_store_annotation(
                "inum",
                "gen_predicate",
                "{ name: fact_count_at_least, args: [grp, $value], phase: post }",
            ),
        ]);
        let (emit_facts, count_kinds, thresholds, draws) =
            StimuliGenerator::compute_store_aware_gen_directives(Some(&annotations));
        assert_eq!(
            emit_facts.get("dname").map(|specs| specs.len()),
            Some(1),
            "@gen_emit_fact must fold into the generation emit map"
        );
        assert_eq!(
            count_kinds.get("uname").map(Vec::as_slice),
            Some(&["cap_name".to_string()][..]),
            "@gen_predicate has_fact must register its kind for the count-prune/prelude"
        );
        assert_eq!(thresholds.get("uname"), Some(&1));
        assert_eq!(
            draws.get("uname"),
            Some(&GenValueDraw::NameOf("cap_name".to_string()))
        );
        assert_eq!(
            count_kinds.get("inum").map(Vec::as_slice),
            Some(&["grp".to_string()][..])
        );
        assert_eq!(thresholds.get("inum"), Some(&1));
        assert_eq!(
            draws.get("inum"),
            Some(&GenValueDraw::IndexUpTo("grp".to_string()))
        );
    }

    #[test]
    fn quantified_separator_absent_directive_keeps_the_fused_default() {
        let (grammar_tree, rule_order) = quantified_separator_fixture();
        for seed in [0u64, 7, 42, 99] {
            let mut generator =
                generator_with_annotations(&grammar_tree, &rule_order, None, seed);
            for sample in generator
                .generate_many(8, Some("file"))
                .expect("directive-free generation should succeed")
            {
                assert!(
                    !sample.contains(';'),
                    "no directive => no separator is ever inserted (seed {seed}): {sample:?}"
                );
            }
        }
    }

    #[test]
    fn quantified_separator_junction_respects_declared_satisfying_spellings() {
        let (grammar_tree, rule_order) = quantified_separator_fixture();
        // The svpp shape: insert "\n"; the grammar's own /\r?\n/ newline token
        // makes "\r\n" a declared already-separated junction spelling.
        let annotations = quantified_separator_annotations(
            "item",
            r#"{ insert: "\n", satisfied_by: ["\n", "\r\n"] }"#,
        );
        let generator =
            generator_with_annotations(&grammar_tree, &rule_order, Some(&annotations), 0);
        let item = rule_ref("item");
        let insert_between = |output: &str, segment: &str| {
            generator
                .quantified_separator_to_insert(&item, output, segment)
                .expect("well-formed policy never errors")
        };
        assert_eq!(insert_between("a", "b"), Some("\n"), "bare junction gets the separator");
        assert_eq!(insert_between("a\n", "b"), None, "output already ends with the separator");
        assert_eq!(insert_between("a", "\nb"), None, "segment already starts with the separator");
        assert_eq!(
            insert_between("a", "\r\nb"),
            None,
            "a declared alternate spelling (CRLF) satisfies the junction"
        );
        assert_eq!(insert_between("", "b"), None, "an empty output never needs separating");
        assert_eq!(insert_between("a", ""), None, "an empty segment never needs separating");
        assert_eq!(
            generator
                .quantified_separator_to_insert(&token("regex", "x"), "a", "b")
                .expect("non-rule-reference elements are policy-free"),
            None,
            "only rule-reference elements consult the policy map"
        );
        assert_eq!(
            generator
                .quantified_separator_to_insert(&rule_ref("file"), "a", "b")
                .expect("directive-free rules are policy-free"),
            None,
            "a rule without the directive never separates"
        );
    }

    #[test]
    fn quantified_separator_malformed_payload_fails_loudly_at_the_join() {
        let (grammar_tree, rule_order) = quantified_separator_fixture();
        // An identifier payload is malformed (the directive requires a quoted
        // string or an object) — the compile verdict poisons `item`, and the
        // first quantifier join over it must surface the compile error.
        let annotations = quantified_separator_annotations("item", "newline");
        let mut generator =
            generator_with_annotations(&grammar_tree, &rule_order, Some(&annotations), 0);
        let err = generator
            .generate_many(8, Some("file"))
            .expect_err("a malformed declared payload must fail generation loudly");
        assert!(
            err.to_string().contains("quantified_separator"),
            "the error must name the directive: {err}"
        );
    }

    /// LEXICAL-ANNOTATIONS.3 — Obligation A (intra-token faithfulness). The line-comment regex
    /// `//[^\n]*(\n|$)` must NEVER be realized via the bare `$` branch when generated inline: every
    /// generated comment must carry its terminating newline, otherwise it swallows whatever follows
    /// on the line (the G.4.7-slice-3 defect). With the old uniform alternation pick ~half of
    /// realizations dropped the newline; the anchor-preference makes it 100%.
    #[test]
    fn obligation_a_line_comment_regex_always_terminates_with_newline() {
        let grammar_tree: HashMap<String, ASTNode> = HashMap::new();
        let rule_order: Vec<String> = Vec::new();
        let pattern = r"//[^\n]*(\n|$)";
        for seed in 0..64u64 {
            let mut g = simple_generator_with_profiles(
                &grammar_tree,
                &rule_order,
                seed,
                StimuliMutationMode::Baseline,
                StimuliConstraintProfile::Baseline,
            );
            let s = g.generate_regex_sample(pattern, "line_comment");
            assert!(s.starts_with("//"), "seed {seed}: expected a // comment, got {s:?}");
            assert!(
                s.ends_with('\n'),
                "seed {seed}: Obligation A — comment must terminate with a newline, got {s:?}"
            );
        }
    }

    /// LEXICAL-ANNOTATIONS.3 — Obligation B (inter-token faithfulness, intra-terminal trailing
    /// guard). The minimal trailing separator is DERIVED from the terminal's regex: open-ended
    /// terminals (trailing `\b`, or a greedy unbounded class repetition) self-terminate with the
    /// smallest separator their tail class cannot absorb; self-delimiting terminals are untouched.
    /// This generalizes the prior `\b`-string-only / space-only rule.
    #[test]
    fn obligation_b_regex_derived_trailing_separator() {
        use StimuliGenerator as G;
        // greedy word/number tails (no `\b`) -> minimal space guard
        assert_eq!(G::regex_terminal_trailing_separator(r"[0-9]+", "782"), Some(" "));
        assert_eq!(
            G::regex_terminal_trailing_separator(r"[A-Za-z_][A-Za-z0-9_]*", "abc"),
            Some(" ")
        );
        // a `[^\n]*` tail can absorb a space, so the minimal guard escalates to a newline
        assert_eq!(G::regex_terminal_trailing_separator(r"x[^\n]*", "xabc"), Some("\n"));
        // trailing `\b` with a word-char tail -> space (subsumed legacy case)
        assert_eq!(G::regex_terminal_trailing_separator(r"endprogram\b", "endprogram"), Some(" "));
        // self-delimiting terminals -> no guard
        assert_eq!(G::regex_terminal_trailing_separator("<", "<"), None);
        assert_eq!(G::regex_terminal_trailing_separator(r#""[^"]*""#, "\"x\""), None);
        // empty candidate -> no guard
        assert_eq!(G::regex_terminal_trailing_separator(r"[0-9]+", ""), None);
    }

    /// GRAMMAR-WELLFORMED.H.5.1.1 — a greedy run of a WHITESPACE-ONLY class needs no
    /// anti-fusion guard (whitespace self-separates; injecting the un-absorbable `"\n"`
    /// is pointless and breaks line-oriented grammars like the SV preprocessor). This
    /// must NOT change behavior for whitespace classes that already include `\n`, for
    /// content-bearing open classes, or for mixed (whitespace+content) classes.
    #[test]
    fn whitespace_only_greedy_tail_gets_no_separator() {
        use StimuliGenerator as G;
        // The regression: `[ \t]+` (inline trivia, excludes \n) used to escalate to `"\n"`;
        // now it correctly yields no guard.
        assert_eq!(G::regex_terminal_trailing_separator(r"[ \t]+", "   "), None);
        assert_eq!(G::regex_terminal_trailing_separator(r"[ ]+", " "), None);
        assert_eq!(G::regex_terminal_trailing_separator(r"[\t]+", "\t"), None);
        // Whitespace classes that already include `\n` were already `None` -> unchanged.
        assert_eq!(G::regex_terminal_trailing_separator(r"[ \t\r\n]+", "  "), None);
        assert_eq!(G::regex_terminal_trailing_separator(r"[ \t\r\n]*", " "), None);
        // BOUNDARY: a class mixing whitespace with content chars is NOT whitespace-only, so
        // the existing escalation still applies (here `[ \ta-z]+` absorbs space -> `"\n"`).
        assert_eq!(G::regex_terminal_trailing_separator(r"[ \ta-z]+", "ab"), Some("\n"));
        // Content-bearing open classes keep their guards (unchanged).
        assert_eq!(G::regex_terminal_trailing_separator(r"[^\n]*", "abc"), Some("\n"));
        assert_eq!(G::regex_terminal_trailing_separator(r"[0-9]+", "7"), Some(" "));
    }

    // LEXICAL-ANNOTATIONS.3c — the minimal-separator chooser for a FORBID list.
    #[test]
    fn forbid_follow_separator_picks_minimal_breaking_char() {
        use StimuliGenerator as G;
        // Forbidding a word-class / a literal operator: a space breaks the boundary.
        assert_eq!(
            G::forbid_follow_separator(&[FollowItem::Regex(r"\w".to_string())]),
            " "
        );
        assert_eq!(
            G::forbid_follow_separator(&[FollowItem::Literal("<".to_string())]),
            " "
        );
        // Forbidding whitespace itself escalates the space candidate to a newline.
        assert_eq!(
            G::forbid_follow_separator(&[FollowItem::Regex(r"[ ]".to_string())]),
            "\n"
        );
    }

    // LEXICAL-ANNOTATIONS.3c — Obligation C (declarative follow-restriction), generation
    // side, END-TO-END through the IR. A FORBID directive (`[>! "<"]`) on `lt := "<"`
    // makes every `lt` surface self-terminate, so two adjacent `lt` tokens in
    // `doc := lt lt` cannot fuse into the distinct longer token `<<` — the deferred
    // `.3d` (i) operator-fusion case the derived obligations cannot infer (a fixed
    // literal has no open-ended regex tail). Faithfulness off (negative-test mode) opts
    // out, and the tokens fuse — proving the restriction (not some unrelated default) is
    // what prevents the fusion.
    #[test]
    fn lexical_forbid_follow_restriction_prevents_distinct_longer_token_fusion() {
        use crate::ast_pipeline::{PipelineConfig, RustASTPipeline};

        let raw_ast = vec![
            serde_json::json!([
                ["rule", "doc"],
                ["rule_reference", "lt"],
                ["rule_reference", "lt"]
            ]),
            serde_json::json!([
                ["rule", "lt"],
                [
                    "lexical_annotation",
                    { "polarity": "forbid", "items": [{ "kind": "literal", "value": "<" }] }
                ],
                ["quoted_string", "<"]
            ]),
        ];
        let (grammar_tree, rule_order, annotations) = RustASTPipeline::new(PipelineConfig::default())
            .transform_from_raw_ast(&raw_ast)
            .expect("transform should succeed");
        let annotations = annotations.expect("annotations present");

        // Faithfulness ON (default): FORBID self-terminates `lt`, so `<` never fuses.
        let mut on_gen = StimuliGenerator::new(
            "lex".to_string(),
            &grammar_tree,
            &rule_order,
            Some(&annotations),
            StimuliConfig {
                seed: Some(7),
                max_depth: 8,
                enforce_word_boundary_spacing: true,
                ..StimuliConfig::default()
            },
        );
        let on = on_gen
            .generate_from_entry("doc")
            .expect("generation (faithful) should succeed");
        assert!(on.contains('<'), "should still emit the `<` tokens: {:?}", on);
        assert!(
            !on.contains("<<"),
            "FORBID restriction must prevent `<`+`<` fusion, got {:?}",
            on
        );

        // Faithfulness OFF (negative-test opt-out): no separator, the tokens fuse.
        let mut off_gen = StimuliGenerator::new(
            "lex".to_string(),
            &grammar_tree,
            &rule_order,
            Some(&annotations),
            StimuliConfig {
                seed: Some(7),
                max_depth: 8,
                enforce_word_boundary_spacing: false,
                ..StimuliConfig::default()
            },
        );
        let off = off_gen
            .generate_from_entry("doc")
            .expect("generation (opt-out) should succeed");
        assert!(
            off.contains("<<"),
            "with faithfulness off the tokens fuse (opt-out), got {:?}",
            off
        );
    }

    // LEXICAL-ANNOTATIONS.4.3 — Obligation A ROUND-TRIP. Every generated line-comment surface must
    // RE-LEX (the comment regex anchored at the start) to EXACTLY itself — a complete token — not a
    // prefix that leaves a dangling tail. This is the faithful-rendering invariant (`render(t)` re-lexes
    // to `t`) verified directly at the lexical level (no full parser needed).
    #[test]
    fn obligation_a_line_comment_roundtrips_via_relex() {
        let grammar_tree: HashMap<String, ASTNode> = HashMap::new();
        let rule_order: Vec<String> = Vec::new();
        let pattern = r"//[^\n]*(\n|$)";
        let relex = Regex::new(&format!("^(?:{})", pattern)).expect("relex compiles");
        for seed in 0..64u64 {
            let mut g = simple_generator_with_profiles(
                &grammar_tree,
                &rule_order,
                seed,
                StimuliMutationMode::Baseline,
                StimuliConstraintProfile::Baseline,
            );
            let s = g.generate_regex_sample(pattern, "line_comment");
            let m = relex
                .find(&s)
                .unwrap_or_else(|| panic!("seed {seed}: comment must re-lex, got {s:?}"));
            assert_eq!(m.start(), 0, "seed {seed}: re-lex must anchor at start of {s:?}");
            assert_eq!(
                m.end(),
                s.len(),
                "seed {seed}: Obligation A round-trip — the emitted comment must re-lex to the WHOLE \
                 surface (a complete token), but matched only {:?} of {s:?}",
                &s[m.start()..m.end()]
            );
        }
    }

    // LEXICAL-ANNOTATIONS.4.3 — Obligation B ROUND-TRIP. In `doc := w w`, with lexical faithfulness ON
    // the two adjacent word terminals render with a separator, so the FIRST word's regex re-lexed at
    // the start of the output matches ONLY the first word (it cannot fuse into the second). With
    // faithfulness OFF the two fuse into a single token — proving the separator (not some unrelated
    // default) is what preserves the boundary.
    #[test]
    fn obligation_b_adjacent_word_terminals_roundtrip_no_fusion() {
        use crate::ast_pipeline::{PipelineConfig, RustASTPipeline};
        let word_pat = r"[A-Za-z_][A-Za-z0-9_]*";
        let raw_ast = vec![
            serde_json::json!([
                ["rule", "doc"],
                ["rule_reference", "w"],
                ["rule_reference", "w"]
            ]),
            serde_json::json!([["rule", "w"], ["regex", word_pat]]),
        ];
        let (grammar_tree, rule_order, _ann) = RustASTPipeline::new(PipelineConfig::default())
            .transform_from_raw_ast(&raw_ast)
            .expect("transform should succeed");
        let relex = Regex::new(&format!("^(?:{})", word_pat)).expect("relex compiles");

        // Faithful ON: the first word's re-lex stops before the second (no fusion).
        let mut on = StimuliGenerator::new(
            "rt".to_string(),
            &grammar_tree,
            &rule_order,
            None,
            StimuliConfig {
                seed: Some(3),
                max_depth: 6,
                enforce_word_boundary_spacing: true,
                ..StimuliConfig::default()
            },
        );
        let s_on = on.generate_from_entry("doc").expect("generation (faithful) should succeed");
        let m_on = relex.find(&s_on).expect("first word must re-lex");
        assert!(
            m_on.end() < s_on.len(),
            "Obligation B round-trip: the first word must NOT consume the whole output (no fusion), \
             got {s_on:?} (match end {})",
            m_on.end()
        );

        // Faithful OFF: the adjacent words fuse into one token (re-lex consumes the whole output).
        let mut off = StimuliGenerator::new(
            "rt".to_string(),
            &grammar_tree,
            &rule_order,
            None,
            StimuliConfig {
                seed: Some(3),
                max_depth: 6,
                enforce_word_boundary_spacing: false,
                ..StimuliConfig::default()
            },
        );
        let s_off = off.generate_from_entry("doc").expect("generation (opt-out) should succeed");
        let m_off = relex.find(&s_off).expect("first word must re-lex");
        assert_eq!(
            m_off.end(),
            s_off.len(),
            "with faithfulness off the adjacent words fuse into one token, got {s_off:?}"
        );
    }

    // LEXICAL-ANNOTATIONS.4.3 — Obligation C GOLDEN + round-trip. The FORBID follow-restriction
    // `[>! "<"]` on `lt := "<"` makes each `lt` self-terminate with the minimal separator the forbidden
    // set cannot absorb (a space), so `doc := lt lt` renders to the exact golden text `"< < "` and the
    // `<` at offset 0 is never immediately followed by another `<`.
    #[test]
    fn obligation_c_forbid_follow_restriction_golden_and_relex() {
        use crate::ast_pipeline::{PipelineConfig, RustASTPipeline};
        let raw_ast = vec![
            serde_json::json!([
                ["rule", "doc"],
                ["rule_reference", "lt"],
                ["rule_reference", "lt"]
            ]),
            serde_json::json!([
                ["rule", "lt"],
                [
                    "lexical_annotation",
                    { "polarity": "forbid", "items": [{ "kind": "literal", "value": "<" }] }
                ],
                ["quoted_string", "<"]
            ]),
        ];
        let (grammar_tree, rule_order, ann) = RustASTPipeline::new(PipelineConfig::default())
            .transform_from_raw_ast(&raw_ast)
            .expect("transform should succeed");
        let ann = ann.expect("annotations present");

        let mut g = StimuliGenerator::new(
            "lex".to_string(),
            &grammar_tree,
            &rule_order,
            Some(&ann),
            StimuliConfig {
                seed: Some(1),
                max_depth: 6,
                enforce_word_boundary_spacing: true,
                ..StimuliConfig::default()
            },
        );
        let s = g.generate_from_entry("doc").expect("generation should succeed");
        // GOLDEN: each `lt` ("<") self-terminates with a single space (the minimal separator a FORBID
        // of "<" cannot absorb), so two of them render to exactly "< < ".
        assert_eq!(s, "< < ", "Obligation C golden faithful output");
        // ROUND-TRIP: the `<` token at offset 0 is exactly one char and is NOT followed by another `<`.
        assert_eq!(s.as_bytes().first(), Some(&b'<'));
        assert_ne!(
            s.as_bytes().get(1),
            Some(&b'<'),
            "FORBID: `<` must never be immediately followed by `<`, got {s:?}"
        );
    }

