    #[test]
    fn word_boundary_spacing_is_successor_aware_no_trailing_separator_for_lone_terminal() {
        // LEXICAL-ANNOTATIONS.5: a lone open-tail terminal (`input\b`) has no successor that could
        // fuse onto it, so word-boundary spacing must NOT bake a spurious trailing separator.
        // (Pre-fix this asserted `ends_with(' ')` — the successor-blind over-insertion this leaf
        // fixes. Inter-token separation is now applied successor-aware by append_generated_segment.)
        let mut grammar_tree = HashMap::new();
        grammar_tree.insert("start".to_string(), token("regex", "input\\b"));
        let rule_order = vec!["start".to_string()];

        let mut generator = StimuliGenerator::new(
            "word_boundary_spacing".to_string(),
            &grammar_tree,
            &rule_order,
            None,
            StimuliConfig {
                seed: Some(2028),
                max_depth: 4,
                max_repeat: 2,
                max_rule_visits: 4,
                target_pending_frontier_extra_stagnation: 8,
                target_generation_timeout_ms: 0,
                target_helper_generation_timeout_ms: 1000,
                recovery_mode: RecoveryStimuliMode::Baseline,
                mutation_mode: StimuliMutationMode::Baseline,
                constraint_profile: StimuliConstraintProfile::Baseline,
                negative_profile: StimuliNegativeProfile::Baseline,
                enforce_word_boundary_spacing: true,
                trace_verbosity: TraceVerbosity::None,
                reach_uncovered_recursive_branches: false,
            },
        );

        let value = generator
            .generate_many(1, None)
            .expect("word-boundary spacing generation should succeed");
        assert!(
            StimuliGenerator::regex_matches_entire(r"input\b", value[0].as_str()),
            "lone word-boundary terminal must satisfy its regex with no trailing separator: {:?}",
            value[0]
        );
        assert!(
            value[0].starts_with("input"),
            "word-boundary sample should preserve regex literal prefix: {:?}",
            value[0]
        );
        assert!(
            !value[0].ends_with(' ') && !value[0].ends_with('\n'),
            "successor-aware spacing must not append a spurious trailing separator for a lone terminal: {:?}",
            value[0]
        );
    }

    #[test]
    fn word_spacing_policy_separates_adjacent_word_segments_in_sequences() {
        let mut grammar_tree = HashMap::new();
        grammar_tree.insert(
            "start".to_string(),
            ASTNode::Sequence {
                elements: vec![
                    token("regex", "module"),
                    token("regex", "automatic"),
                    token("regex", "[A-Za-z]+"),
                ],
            },
        );
        let rule_order = vec!["start".to_string()];

        let mut generator = StimuliGenerator::new(
            "word_spacing_sequence".to_string(),
            &grammar_tree,
            &rule_order,
            None,
            StimuliConfig {
                seed: Some(2029),
                max_depth: 4,
                max_repeat: 2,
                max_rule_visits: 4,
                target_pending_frontier_extra_stagnation: 8,
                target_generation_timeout_ms: 0,
                target_helper_generation_timeout_ms: 1000,
                recovery_mode: RecoveryStimuliMode::Baseline,
                mutation_mode: StimuliMutationMode::Baseline,
                constraint_profile: StimuliConstraintProfile::Baseline,
                negative_profile: StimuliNegativeProfile::Baseline,
                enforce_word_boundary_spacing: true,
                trace_verbosity: TraceVerbosity::None,
                reach_uncovered_recursive_branches: false,
            },
        );

        let value = generator
            .generate_many(1, None)
            .expect("word-segment spacing generation should succeed");
        assert!(
            value[0].starts_with("module automatic "),
            "word spacing should separate adjacent lexical segments: {:?}",
            value[0]
        );
        let parts: Vec<&str> = value[0].split_whitespace().collect();
        assert!(
            parts.len() >= 3,
            "word spacing sequence should keep lexical segments distinct: {:?}",
            value[0]
        );
        assert!(
            StimuliGenerator::regex_matches_entire("module", parts[0]),
            "first segment must satisfy originating regex: {:?}",
            value[0]
        );
        assert!(
            StimuliGenerator::regex_matches_entire("automatic", parts[1]),
            "second segment must satisfy originating regex: {:?}",
            value[0]
        );
        assert!(
            StimuliGenerator::regex_matches_entire("[A-Za-z]+", parts[2]),
            "third segment must satisfy originating regex: {:?}",
            value[0]
        );
    }

    #[test]
    fn word_boundary_spacing_not_inserted_before_non_fusable_closing_delimiter() {
        // LEXICAL-ANNOTATIONS.5 regression lock: an open-tail word terminal (`[A-Za-z]+`)
        // immediately followed by a literal closing delimiter `)` must NOT be separated — the
        // delimiter cannot fuse with the identifier, so `name)` (not `name )`) is the faithful,
        // re-parsable surface. Pre-fix the eager guard baked a trailing space → `name )` (the regex
        // `(*VERB )` / `(?P>NAME )` / `(?(COND ))` defect). Separation is now successor-aware.
        let mut grammar_tree = HashMap::new();
        grammar_tree.insert(
            "start".to_string(),
            ASTNode::Sequence {
                elements: vec![token("regex", "[A-Za-z]+"), token("regex", "\\)")],
            },
        );
        let rule_order = vec!["start".to_string()];

        let mut generator = StimuliGenerator::new(
            "word_boundary_closing_delim".to_string(),
            &grammar_tree,
            &rule_order,
            None,
            StimuliConfig {
                seed: Some(4242),
                max_depth: 4,
                max_repeat: 2,
                max_rule_visits: 4,
                target_pending_frontier_extra_stagnation: 8,
                target_generation_timeout_ms: 0,
                target_helper_generation_timeout_ms: 1000,
                recovery_mode: RecoveryStimuliMode::Baseline,
                mutation_mode: StimuliMutationMode::Baseline,
                constraint_profile: StimuliConstraintProfile::Baseline,
                negative_profile: StimuliNegativeProfile::Baseline,
                enforce_word_boundary_spacing: true,
                trace_verbosity: TraceVerbosity::None,
                reach_uncovered_recursive_branches: false,
            },
        );

        let value = generator
            .generate_many(1, None)
            .expect("closing-delimiter spacing generation should succeed");
        assert!(
            StimuliGenerator::regex_matches_entire(r"[A-Za-z]+\)", value[0].as_str()),
            "open-tail terminal + closing delimiter must re-lex as `name)` with no interposed separator: {:?}",
            value[0]
        );
        assert!(
            !value[0].contains(' ') && !value[0].contains('\n'),
            "successor-aware spacing must not insert a separator before a non-fusable `)`: {:?}",
            value[0]
        );
    }

    #[test]
    fn lexical_annotations_6_matched_text_rule_generates_one_fused_token() {
        // LEXICAL-ANNOTATIONS.6 (case c): a `$text`/MatchedText rule is ONE lexical token, so a
        // self-hosting char-sequence body (`name := [a-z] [a-z] [a-z]`) must render FUSED (`abc`),
        // never `a b c`. Pre-fix the concat join separated its own word chars → the `(?P=a b c)`
        // reject. The cohesion signal is the DECLARED return shape (no new annotation — Level 1).
        let mut grammar_tree = HashMap::new();
        grammar_tree.insert(
            "name".to_string(),
            ASTNode::Sequence {
                elements: vec![
                    token("regex", "[a-z]"),
                    token("regex", "[a-z]"),
                    token("regex", "[a-z]"),
                ],
            },
        );
        let rule_order = vec!["name".to_string()];

        let mut annotations = Annotations::default();
        annotations.branch_return_annotations.insert(
            "name".to_string(),
            vec![Some(crate::ast_pipeline::BranchAnnotation {
                annotation_type: "return".to_string(),
                annotation_content: "$text".to_string(),
                parsed_ast: Some(UnifiedReturnAST::MatchedText),
            })],
        );

        let mut generator = StimuliGenerator::new(
            "rgx".to_string(),
            &grammar_tree,
            &rule_order,
            Some(&annotations),
            StimuliConfig {
                seed: Some(11),
                enforce_word_boundary_spacing: true,
                ..StimuliConfig::default()
            },
        );
        let out = generator
            .generate_from_entry("name")
            .expect("atomic $text rule generation should succeed");
        assert!(
            !out.contains(' ') && !out.contains('\n'),
            "atomic $text rule must render as one fused token (no internal separators): {:?}",
            out
        );
        assert!(
            StimuliGenerator::regex_matches_entire("[a-z]{3}", &out),
            "atomic $text rule body should re-lex to its 3 fused letters: {:?}",
            out
        );
    }

    #[test]
    fn lexical_annotations_6_token_fuses_with_following_atomic_rule_reference() {
        // LEXICAL-ANNOTATIONS.6 (case b): in a NON-atomic rule (`cond := "R" digits`), the concat
        // join must NOT separate the `"R"` literal from a following atomic-token-rule segment
        // (`digits` is `$text`) — `R12`, never `R 1 2`. CONTROL: with `digits` NOT atomic the join DOES
        // separate, proving the atomicity signal (not some unrelated default) is what fuses.
        let mut grammar_tree = HashMap::new();
        grammar_tree.insert(
            "cond".to_string(),
            ASTNode::Sequence {
                elements: vec![token("quoted_string", "R"), token("rule_reference", "digits")],
            },
        );
        grammar_tree.insert(
            "digits".to_string(),
            ASTNode::Sequence {
                elements: vec![token("regex", "[0-9]"), token("regex", "[0-9]")],
            },
        );
        let rule_order = vec!["cond".to_string(), "digits".to_string()];

        // `digits` atomic ($text) → fused.
        let mut atomic_ann = Annotations::default();
        atomic_ann.branch_return_annotations.insert(
            "digits".to_string(),
            vec![Some(crate::ast_pipeline::BranchAnnotation {
                annotation_type: "return".to_string(),
                annotation_content: "$text".to_string(),
                parsed_ast: Some(UnifiedReturnAST::MatchedText),
            })],
        );
        let mut fused_gen = StimuliGenerator::new(
            "rgx".to_string(),
            &grammar_tree,
            &rule_order,
            Some(&atomic_ann),
            StimuliConfig {
                seed: Some(5),
                enforce_word_boundary_spacing: true,
                ..StimuliConfig::default()
            },
        );
        let fused = fused_gen
            .generate_from_entry("cond")
            .expect("atomic-segment cohesion generation should succeed");
        assert!(
            StimuliGenerator::regex_matches_entire("R[0-9]{2}", &fused),
            "a literal followed by an atomic-token-rule reference must fuse to `R12`: {:?}",
            fused
        );

        // CONTROL: `digits` NOT atomic → the join separates the word chars (atomicity is the cause).
        let mut split_gen = StimuliGenerator::new(
            "rgx".to_string(),
            &grammar_tree,
            &rule_order,
            None,
            StimuliConfig {
                seed: Some(5),
                enforce_word_boundary_spacing: true,
                ..StimuliConfig::default()
            },
        );
        let split = split_gen
            .generate_from_entry("cond")
            .expect("control generation should succeed");
        assert!(
            split.contains(' '),
            "without the atomicity signal the concat join separates the word chars: {:?}",
            split
        );
    }

    #[test]
    fn lexical_annotations_6_transform_rule_is_lexically_atomic() {
        // LEXICAL-ANNOTATIONS.6: the SECOND atomicity signal — a `@transform` directive (the real
        // regex `digits = digit+ @transform: str::parse::<usize>()` rule has no `$text`). A
        // `@transform` rule's surface is one scalar token, so its body must render fused (`12`).
        let mut grammar_tree = HashMap::new();
        grammar_tree.insert(
            "digits".to_string(),
            ASTNode::Sequence {
                elements: vec![token("regex", "[0-9]"), token("regex", "[0-9]")],
            },
        );
        let rule_order = vec!["digits".to_string()];

        let mut annotations = Annotations::default();
        annotations.semantic_annotations.insert(
            "digits".to_string(),
            vec![SemanticAnnotation::Named {
                name: "transform".to_string(),
                ast: UnifiedSemanticAST::TransformExpr {
                    expression: "str::parse::<usize>().unwrap_or(0)".to_string(),
                },
            }],
        );

        let mut generator = StimuliGenerator::new(
            "rgx".to_string(),
            &grammar_tree,
            &rule_order,
            Some(&annotations),
            StimuliConfig {
                seed: Some(13),
                enforce_word_boundary_spacing: true,
                ..StimuliConfig::default()
            },
        );
        assert!(
            generator.rule_is_lexically_atomic("digits"),
            "a @transform rule must be classified lexically atomic"
        );
        let out = generator
            .generate_from_entry("digits")
            .expect("@transform atomic rule generation should succeed");
        assert!(
            StimuliGenerator::regex_matches_entire("[0-9]{2}", &out),
            "@transform rule body should render as one fused scalar token (no internal space): {:?}",
            out
        );
    }

    #[test]
    fn store_aware_gen_count_predicate_necessary_condition() {
        // STORE-AWARE-GEN.3: a rule gated by `fact_count_at_least(K, $ref)` is UNSATISFIABLE when zero
        // `K` facts exist (no positive reference can match an empty fact set), and becomes satisfiable
        // once ≥ 1 `K` fact is emitted. This is the sound necessary condition that prunes an invalid
        // numeric backreference (`\98495` with no capture groups) and is evaluated via the SAME
        // `evaluate_predicate` the parser uses.
        let mut grammar_tree = HashMap::new();
        grammar_tree.insert("start".to_string(), token("quoted_string", "x"));
        let rule_order = vec!["start".to_string()];
        let mut generator = simple_generator(&grammar_tree, &rule_order, 1);
        generator.store_aware_gen = true;
        generator
            .gen_count_kinds
            .insert("backref".to_string(), vec!["grp".to_string()]);

        assert!(
            !generator.gen_count_predicate_satisfiable("backref"),
            "with zero `grp` facts the count predicate must be unsatisfiable (the rule must backtrack)"
        );
        generator.gen_semantic_state.emit_fact(SemanticFactSpec {
            kind: "grp".to_string(),
            name: crate::ast_pipeline::SemanticRuntimeValue::Identifier("g1".to_string()),
            attributes: vec![],
        });
        assert!(
            generator.gen_count_predicate_satisfiable("backref"),
            "after emitting one `grp` fact the count predicate must be satisfiable"
        );
        assert!(
            generator.gen_count_predicate_satisfiable("unrelated_rule"),
            "a rule with no count predicate is always satisfiable"
        );
    }

    #[test]
    fn store_aware_gen_off_for_predicate_free_grammar() {
        // STORE-AWARE-GEN.3: the no-op gate — a grammar with no generative `fact_count_at_least`
        // predicate disables the ENTIRE store-aware path (byte-identical generation for json/ebnf/SV).
        let mut grammar_tree = HashMap::new();
        grammar_tree.insert("start".to_string(), token("regex", "[a-z]+"));
        let rule_order = vec!["start".to_string()];
        let generator = simple_generator(&grammar_tree, &rule_order, 1);
        assert!(
            !generator.store_aware_gen,
            "a grammar without a generative fact_count_at_least predicate must not activate store-aware generation"
        );
        assert!(generator.gen_count_kinds.is_empty());
        assert!(generator.gen_emit_facts.is_empty());
        // STORE-AWARE-GEN.4b.2: the name-gate map is likewise empty for a predicate-free grammar, so
        // the declare-then-use name-prelude path is inert (byte-identical generation).
        assert!(generator.gen_name_gate.is_empty());
    }

    #[test]
    fn store_aware_gen_name_whole_render_resolution() {
        // STORE-AWARE-GEN.4b.2: an `@emit_fact` name resolves to the producer rule's WHOLE render only
        // for an UNDOTTED `$ref` (`name: $body` on a `declared_X := X_identifier -> {body:$1.body}`
        // passthrough). A dotted ref (`$head.body`) and a LITERAL name (regex's `name: capture`) are
        // left verbatim, so regex and every non-cohort emit stay byte-identical.
        assert!(StimuliGenerator::emit_name_is_whole_render(
            &SemanticRuntimeValue::RuleReference("body".to_string())
        ));
        assert!(!StimuliGenerator::emit_name_is_whole_render(
            &SemanticRuntimeValue::RuleReference("head.body".to_string())
        ));
        assert!(!StimuliGenerator::emit_name_is_whole_render(
            &SemanticRuntimeValue::Identifier("capture".to_string())
        ));
        assert!(!StimuliGenerator::emit_name_is_whole_render(
            &SemanticRuntimeValue::String("literal".to_string())
        ));
    }

    #[test]
    fn store_aware_gen_producer_family_satisfies_gate() {
        // STORE-AWARE-GEN.4b.2: a producer may declare for a consumer's name gate only when its
        // `declaration_family` equals the gate's REQUIRED family (when `fact_attribute_equals`) and is
        // not one the gate's `lacks_fact_attribute_equals` EXCLUDES.
        let family_attr = |value: &str| crate::ast_pipeline::UnifiedSemanticProperty {
            key: "declaration_family".to_string(),
            value: UnifiedSemanticValue::Identifier(value.to_string()),
        };
        let class_producer = SemanticFactSpec {
            kind: "type_name".to_string(),
            name: SemanticRuntimeValue::RuleReference("body".to_string()),
            attributes: vec![family_attr("class")],
        };
        // Required family matches.
        assert!(StimuliGenerator::producer_family_satisfies_gate(
            &class_producer,
            &NameGate { kind: "type_name".to_string(), family: Some("class".to_string()), excluded_families: vec![] },
        ));
        // Required family differs.
        assert!(!StimuliGenerator::producer_family_satisfies_gate(
            &class_producer,
            &NameGate { kind: "type_name".to_string(), family: Some("covergroup".to_string()), excluded_families: vec![] },
        ));
        // No required family but the producer's family is EXCLUDED (the lacks_fact case).
        assert!(!StimuliGenerator::producer_family_satisfies_gate(
            &class_producer,
            &NameGate { kind: "type_name".to_string(), family: None, excluded_families: vec!["class".to_string()] },
        ));
        // No required family, not excluded → ok.
        assert!(StimuliGenerator::producer_family_satisfies_gate(
            &class_producer,
            &NameGate { kind: "type_name".to_string(), family: None, excluded_families: vec!["typedef".to_string()] },
        ));
    }

    #[test]
    fn store_aware_gen_store_name_for_gate_matches_kind_and_family() {
        // STORE-AWARE-GEN.4b.2: the consumer reads the live store for the name its upstream producer
        // declared, selecting by kind and (optionally) `declaration_family`. The MOST-RECENT match wins
        // (the prelude's own declaration). A query whose kind/family is absent returns `None`, so the
        // consumer just renders normally and does not (mis-)witness.
        let grammar_tree = HashMap::new();
        let rule_order: Vec<String> = vec![];
        let mut generator = simple_generator(&grammar_tree, &rule_order, 1);
        let emit = |g: &mut StimuliGenerator, name: &str, family: &str| {
            g.gen_semantic_state.emit_fact(SemanticFactSpec {
                kind: "type_name".to_string(),
                name: SemanticRuntimeValue::Identifier(name.to_string()),
                attributes: vec![crate::ast_pipeline::UnifiedSemanticProperty {
                    key: "declaration_family".to_string(),
                    value: UnifiedSemanticValue::Identifier(family.to_string()),
                }],
            });
        };
        emit(&mut generator, "cg_a", "covergroup");
        emit(&mut generator, "cls_a", "class");
        emit(&mut generator, "cg_b", "covergroup");

        assert_eq!(
            generator.store_name_for_gate("type_name", Some("covergroup")).as_deref(),
            Some("cg_b"),
            "most-recent covergroup name wins"
        );
        assert_eq!(
            generator.store_name_for_gate("type_name", Some("class")).as_deref(),
            Some("cls_a")
        );
        assert_eq!(
            generator.store_name_for_gate("type_name", None).as_deref(),
            Some("cg_b"),
            "no required family → most-recent fact of the kind"
        );
        assert_eq!(generator.store_name_for_gate("type_name", Some("nettype")), None);
        assert_eq!(generator.store_name_for_gate("let_name", None), None);
    }

    #[test]
    fn store_aware_gen_mandatory_leading_rule_reference_descends_carrier() {
        // STORE-AWARE-GEN.4b.4: a carrier's MANDATORY-first element resolves to its leading rule
        // reference — `R := S t` and `R := S` both descend to `S` (mirroring
        // `known_unscoped_block_type_identifier := checked_type_identifier packed_dimension*` and
        // `known_unscoped_block_covergroup_identifier := known_unscoped_covergroup_type_identifier`).
        // An ordered-choice-led or terminal-led body returns `None` (no single guaranteed mandatory
        // first rule), so the prelude never arms on a rule the use-site may not render.
        let mut g = HashMap::new();
        g.insert(
            "seq_carrier".to_string(),
            ASTNode::Sequence {
                elements: vec![rule_ref("inner"), token("regex", "x")],
            },
        );
        g.insert("ref_carrier".to_string(), rule_ref("inner"));
        g.insert(
            "or_carrier".to_string(),
            ASTNode::Or {
                alternatives: vec![rule_ref("inner"), token("regex", "y")],
            },
        );
        g.insert("term_carrier".to_string(), token("regex", "z"));
        g.insert("inner".to_string(), token("regex", "[a-z]+"));
        let order: Vec<String> = g.keys().cloned().collect();
        let generator = simple_generator(&g, &order, 1);
        assert_eq!(
            generator
                .mandatory_leading_rule_reference("seq_carrier")
                .as_deref(),
            Some("inner")
        );
        assert_eq!(
            generator
                .mandatory_leading_rule_reference("ref_carrier")
                .as_deref(),
            Some("inner")
        );
        assert_eq!(
            generator.mandatory_leading_rule_reference("or_carrier"),
            None,
            "an Or-led body has no single guaranteed mandatory first rule"
        );
        assert_eq!(
            generator.mandatory_leading_rule_reference("term_carrier"),
            None,
            "a terminal-led body has no leading rule reference"
        );
    }

    #[test]
    fn store_aware_gen_name_gate_via_mandatory_prefix_inherits_inner_gate() {
        // STORE-AWARE-GEN.4b.4: a non-gated CARRIER inherits the name gate of the inner rule its
        // mandatory-first prefix reaches (so the declare-then-use prelude arms on the inner rule that
        // actually renders); a DIRECTLY-gated rule short-circuits at depth 0 (identical to the pre-4b.4
        // direct lookup); an ungated rule reaching no gate returns `None` (no prelude).
        let mut g = HashMap::new();
        g.insert(
            "carrier".to_string(),
            ASTNode::Sequence {
                elements: vec![rule_ref("inner_gated"), token("regex", "x")],
            },
        );
        g.insert("inner_gated".to_string(), token("regex", "[a-z]+"));
        g.insert("ungated".to_string(), token("regex", "[0-9]+"));
        let order: Vec<String> = g.keys().cloned().collect();
        let mut generator = simple_generator(&g, &order, 1);
        // Arm a name gate on the INNER rule only (simulating `compute_name_gates`' SV result).
        generator.gen_name_gate.insert(
            "inner_gated".to_string(),
            NameGate {
                kind: "type_name".to_string(),
                family: None,
                excluded_families: vec![],
            },
        );
        let via_carrier = generator
            .name_gate_via_mandatory_prefix("carrier")
            .expect("a non-gated carrier inherits its inner rule's name gate");
        assert_eq!(via_carrier.0, "inner_gated", "armed on the inner gated rule");
        assert_eq!(via_carrier.1.kind, "type_name");
        let direct = generator
            .name_gate_via_mandatory_prefix("inner_gated")
            .expect("a directly-gated rule short-circuits at depth 0");
        assert_eq!(direct.0, "inner_gated");
        assert!(
            generator.name_gate_via_mandatory_prefix("ungated").is_none(),
            "an ungated rule reaching no gate yields no prelude"
        );
    }

    #[test]
    fn store_aware_gen_name_gate_discovers_gate_behind_leading_prefix_and_or() {
        // STORE-AWARE-GEN.4b.7: the `.4b.4` mandatory-FIRST chain dies on a leading optional/keyword
        // prefix; the broadened structural leg scans ALL mandatory sequence elements (skipping a leading
        // optional `(kw_static)?` and stepping past a leading keyword rule that renders no gate) and
        // descends Or alternatives, so a gate buried behind that prefix and inside an ordered choice is
        // discovered — BUT only when the render is UNAVOIDABLY store-gated (`mandatory_reach_gate` against
        // an empty store), so a rule with an empty-store-renderable escape is NOT armed. Mirrors
        // `extern_constraint_declaration_sv_2017 := (kw_static)? kw_constraint class_scope …` →
        // `class_scope_type := ( scoped_… | known_unscoped_class_scope_class_identifier | … ) …`, whose
        // `scoped_…` alternative carries a `lacks_fact` type_name gate (so the Or has NO ungated escape),
        // versus `associative_dimension := lbrack data_type rbrack`, where `data_type` renders a builtin
        // with no gate (an escape).
        let mut g = HashMap::new();
        g.insert(
            "extern_like".to_string(),
            ASTNode::Sequence {
                elements: vec![
                    // `( kw_static )?` — a leading OPTIONAL the `.4b.4` chain cannot step over.
                    ASTNode::Quantified {
                        element: Box::new(rule_ref("kw_static")),
                        quantifier: "?".to_string(),
                    },
                    // `kw_constraint` — a leading mandatory KEYWORD rule that renders no gate.
                    rule_ref("kw_constraint"),
                    // the gated content rule reached only after the prefix.
                    rule_ref("scope"),
                ],
            },
        );
        g.insert("kw_static".to_string(), token("regex", "static"));
        g.insert("kw_constraint".to_string(), token("regex", "constraint"));
        g.insert("scope".to_string(), rule_ref("scope_type"));
        g.insert(
            "scope_type".to_string(),
            // `( escape_alt | gated_alt )` — the positive gate is the SECOND alternative (as in the real
            // grammar, where `scoped_class_scope_identifier` precedes the class gate). BOTH alternatives
            // are store-gated, so the Or has NO ungated escape (the prelude is unavoidable + safe).
            ASTNode::Or {
                alternatives: vec![rule_ref("escape_alt"), rule_ref("gated_alt")],
            },
        );
        // `escape_alt` carries a (negative-style) store gate but NO positive name gate — mirrors
        // `scoped_class_scope_identifier`'s `lacks_fact` type_name gate: gated for reachability, yet not a
        // declare-then-use producer-matchable name gate.
        g.insert("escape_alt".to_string(), token("regex", "[a-z]+::[a-z]+"));
        g.insert("gated_alt".to_string(), token("regex", "[a-z]+"));
        // A control rule whose mandatory prefix reaches NO gate (a plain terminal tail) — must yield `None`.
        g.insert(
            "no_gate".to_string(),
            ASTNode::Sequence {
                elements: vec![rule_ref("kw_constraint"), token("regex", "[0-9]+")],
            },
        );
        // A rule whose content rule (`dim_type`) has an empty-store-renderable ESCAPE (`builtin`, no gate)
        // — mirrors `associative_dimension := lbrack data_type rbrack`; the guard must drop it.
        g.insert(
            "escape_dim".to_string(),
            ASTNode::Sequence {
                elements: vec![rule_ref("kw_constraint"), rule_ref("dim_type")],
            },
        );
        g.insert(
            "dim_type".to_string(),
            ASTNode::Or {
                alternatives: vec![rule_ref("builtin"), rule_ref("gated_alt")],
            },
        );
        g.insert("builtin".to_string(), token("regex", "int"));
        let order: Vec<String> = g.keys().cloned().collect();
        let mut generator = simple_generator(&g, &order, 1);
        // The positive (producer-matchable) name gate on `gated_alt`.
        generator.gen_name_gate.insert(
            "gated_alt".to_string(),
            NameGate {
                kind: "type_name".to_string(),
                family: Some("class".to_string()),
                excluded_families: vec![],
            },
        );
        // Reachability store-gates (any of the 5 fact-query primitives): both `escape_alt` and `gated_alt`
        // are store-gated on `type_name`, so `scope_type`'s Or has no ungated escape; `builtin` is NOT
        // gated, so `dim_type`'s Or DOES.
        generator
            .reach_gate_kinds
            .insert("escape_alt".to_string(), vec!["type_name".to_string()]);
        generator
            .reach_gate_kinds
            .insert("gated_alt".to_string(), vec!["type_name".to_string()]);
        let via_prefix = generator
            .name_gate_via_mandatory_prefix("extern_like")
            .expect("a gate behind a leading optional/keyword prefix and inside an Or is discovered");
        assert_eq!(
            via_prefix.0, "gated_alt",
            "armed on the positive-gated Or alternative the render routes through, not the escape one"
        );
        assert_eq!(via_prefix.1.family.as_deref(), Some("class"));
        assert!(
            generator.name_gate_via_mandatory_prefix("no_gate").is_none(),
            "a mandatory prefix reaching no gate still yields no prelude (no over-reach)"
        );
        assert!(
            generator.name_gate_via_mandatory_prefix("escape_dim").is_none(),
            "a content rule with an empty-store-renderable escape is NOT armed (the .4b.7 guard)"
        );
    }

    #[test]
    fn store_aware_gen_name_gate_discovers_offpath_sibling_gate_along_path() {
        // STORE-AWARE-GEN.4b.10: a target reached THROUGH a host whose name gate is a mandatory off-path
        // SIBLING of the on-path element gets no prelude from the `.4b.4`/`.4b.7` mandatory-prefix legs
        // (they inspect only the TARGET's own prefix) nor the direct-hop scan (the gate is not a hop
        // RULE). Mirrors `constraint_set` reached via `extern_constraint_declaration_sv_2017 :=
        // ( kw_static )? kw_constraint class_scope constraint_identifier constraint_block` at hop site
        // `root/s4`: the `class_scope` gate is a mandatory sibling of the on-path `constraint_block`. The
        // off-path-sibling leg walks the hop's node_path and finds the gate on the sibling (reusing
        // `gate_in_mandatory_prefix_node`'s unavoidably-store-gated guard) — but skips the ON-PATH index
        // and yields None when no off-path sibling is store-gated.
        let mut g = HashMap::new();
        // host := kw_constraint scope[gated] constraint_id body — the reach path forces s3 (`body`), and
        // `scope` (s1) is the off-path gated sibling (the `class_scope` analogue).
        g.insert(
            "host".to_string(),
            ASTNode::Sequence {
                elements: vec![
                    rule_ref("kw_constraint"), // s0 keyword sibling — no gate
                    rule_ref("scope"),         // s1 GATED off-path sibling (class_scope analogue)
                    rule_ref("constraint_id"), // s2 ungated free-name sibling
                    rule_ref("body"),          // s3 ON-PATH element (constraint_block analogue)
                ],
            },
        );
        g.insert("kw_constraint".to_string(), token("regex", "constraint"));
        g.insert("scope".to_string(), rule_ref("scope_type"));
        g.insert(
            "scope_type".to_string(),
            // `( escape_alt | gated_alt )` — both store-gated (no ungated escape), positive gate second,
            // exactly as the real `class_scope_type` Or.
            ASTNode::Or {
                alternatives: vec![rule_ref("escape_alt"), rule_ref("gated_alt")],
            },
        );
        g.insert("escape_alt".to_string(), token("regex", "[a-z]+::[a-z]+"));
        g.insert("gated_alt".to_string(), token("regex", "[a-z]+"));
        g.insert("constraint_id".to_string(), token("regex", "[a-z]+"));
        g.insert("body".to_string(), token("regex", "[{][}]"));
        // A clean host whose off-path siblings are all ungated (keyword + free-name) — must yield None.
        g.insert(
            "clean_host".to_string(),
            ASTNode::Sequence {
                elements: vec![
                    rule_ref("kw_constraint"),
                    rule_ref("constraint_id"),
                    rule_ref("body"),
                ],
            },
        );
        let order: Vec<String> = g.keys().cloned().collect();
        let mut generator = simple_generator(&g, &order, 1);
        generator.gen_name_gate.insert(
            "gated_alt".to_string(),
            NameGate {
                kind: "type_name".to_string(),
                family: Some("class".to_string()),
                excluded_families: vec![],
            },
        );
        generator
            .reach_gate_kinds
            .insert("escape_alt".to_string(), vec!["type_name".to_string()]);
        generator
            .reach_gate_kinds
            .insert("gated_alt".to_string(), vec!["type_name".to_string()]);
        // The reach path forces the on-path element s3 (`body`); s1 (`scope`) is the off-path gated sibling.
        let hops = vec![("host".to_string(), "root/s3".to_string())];
        let via_sibling = generator
            .name_gate_via_offpath_sibling(&hops)
            .expect("a gate on a mandatory off-path sibling along the reach path is discovered");
        assert_eq!(
            via_sibling.0, "gated_alt",
            "armed on the off-path sibling's positive name gate"
        );
        assert_eq!(via_sibling.1.family.as_deref(), Some("class"));
        // A host whose off-path siblings are all ungated yields no prelude (no over-reach).
        let clean_hops = vec![("clean_host".to_string(), "root/s2".to_string())];
        assert!(
            generator.name_gate_via_offpath_sibling(&clean_hops).is_none(),
            "no off-path sibling is store-gated ⇒ no prelude"
        );
        // The gated element ON the path (s1 = `scope`) is NOT an off-path sibling: forcing s1 leaves
        // s0/s2/s3 as siblings, none gated → None (the leg must skip the on-path index).
        let onpath_hops = vec![("host".to_string(), "root/s1".to_string())];
        assert!(
            generator.name_gate_via_offpath_sibling(&onpath_hops).is_none(),
            "the gated element is ON the path (not an off-path sibling) ⇒ not armed via this leg"
        );
    }

    #[test]
    fn store_aware_gen_diversifies_free_name_colliding_with_type_name_fact() {
        // STORE-AWARE-GEN.4b.8: collide-aware free-name diversity (sub-cohort 3B-iii,
        // `property_qualifier`). The reach-context class `\foo` emits a `type_name` fact; a FREE
        // declaring identifier that re-renders the SAME canonical `\foo` is misparsed by a type-first
        // ordered choice (`data_type_or_implicit := data_type | implicit_data_type`), so the witness
        // generator must render a DISTINCT name. Keyed on the grammar's OWN name-gate kinds
        // (parser-agnostic), never a rule name; inert outside the witness pass and when no collision
        // exists (byte-identical); a producer's own first declaration (empty store) is never
        // diversified, so the most-recent-fact read-back (`store_name_for_gate`) stays consistent.
        let mut g = HashMap::new();
        g.insert("id".to_string(), token("regex", "[a-zA-Z_][a-zA-Z0-9_]*"));
        let order: Vec<String> = g.keys().cloned().collect();
        let mut generator = simple_generator(&g, &order, 1);
        // A positive name gate consuming `type_name` makes the grammar store-aware (capability gate).
        generator.gen_name_gate.insert(
            "consumer".to_string(),
            NameGate {
                kind: "type_name".to_string(),
                family: Some("class".to_string()),
                excluded_families: vec![],
            },
        );
        // Witness-pass scope: an armed (minimal) reach plan.
        generator.reach_plan = Some(ActiveReachPlan::from_directives(&[], 0));

        // Empty store ⇒ no collision ⇒ a producer's own first declaration renders UNCHANGED.
        assert!(!generator.free_name_collides_gate_kind("\\foo"));
        assert_eq!(
            generator.diversify_free_name_avoiding_gate_collision("\\foo ".to_string()),
            "\\foo "
        );

        // The reach-context class declares the `type_name` fact `\foo`.
        generator.gen_semantic_state.emit_fact(SemanticFactSpec {
            kind: "type_name".to_string(),
            name: SemanticRuntimeValue::Identifier("\\foo".to_string()),
            attributes: vec![],
        });

        // Now a FREE identifier re-rendering `\foo` collides and is diversified to a DISTINCT name,
        // preserving the trailing escaped-identifier whitespace terminator; the new name is clear.
        assert!(generator.free_name_collides_gate_kind("\\foo"));
        let diversified =
            generator.diversify_free_name_avoiding_gate_collision("\\foo ".to_string());
        assert_ne!(diversified, "\\foo ", "the colliding free name must be diversified");
        assert!(
            diversified.starts_with("\\foo_") && diversified.ends_with(' '),
            "distinct id-continue suffix + preserved terminator: {:?}",
            diversified
        );
        assert!(
            !generator.free_name_collides_gate_kind(diversified.trim()),
            "the diversified name no longer collides with the type_name fact"
        );

        // Precision: a fact under a kind NO name-gate consumes is NOT a collision.
        generator.gen_semantic_state.emit_fact(SemanticFactSpec {
            kind: "package_name".to_string(),
            name: SemanticRuntimeValue::Identifier("\\pkg".to_string()),
            attributes: vec![],
        });
        assert!(!generator.free_name_collides_gate_kind("\\pkg"));

        // A multi-token literal hint is never a free declaring identifier ⇒ untouched.
        assert_eq!(
            generator
                .diversify_free_name_avoiding_gate_collision("case (a) default: ; endcase".to_string()),
            "case (a) default: ; endcase"
        );

        // Inert OUTSIDE the witness pass (no reach plan) ⇒ byte-identical even with a live collision.
        generator.reach_plan = None;
        assert_eq!(
            generator.diversify_free_name_avoiding_gate_collision("\\foo ".to_string()),
            "\\foo "
        );
    }

    #[test]
    fn store_aware_gen_prefers_self_bootstrapping_host_branch() {
        // STORE-AWARE-GEN.4b.6: two producers can share a body yet differ in HOST BRANCH. The typedef-
        // ALIAS branch (`kw_typedef class_type declared_class_alias_identifier`) carries a mandatory
        // same-store-gated sibling — `class_type` descends to a `has_fact(type_name)` gate — so its
        // forced prelude derivation cannot parse in an empty store; the FORWARD branch
        // (`kw_typedef kw_class declared_forward_class_identifier`) is clean.
        // `reach_path_renders_unsatisfiable_gate` flags the alias host path and not the forward one.
        let mut g = HashMap::new();
        g.insert(
            "type_declaration".to_string(),
            ASTNode::Or {
                alternatives: vec![
                    // branch o0 — ALIAS: kw_typedef class_type alias_producer  (class_type is gated)
                    ASTNode::Sequence {
                        elements: vec![
                            token("regex", "typedef"),
                            rule_ref("class_type"),
                            rule_ref("alias_producer"),
                        ],
                    },
                    // branch o1 — FORWARD: kw_typedef kw_class forward_producer  (clean)
                    ASTNode::Sequence {
                        elements: vec![
                            token("regex", "typedef"),
                            token("regex", "class"),
                            rule_ref("forward_producer"),
                        ],
                    },
                ],
            },
        );
        g.insert("class_type".to_string(), rule_ref("checked_type_identifier"));
        g.insert("checked_type_identifier".to_string(), token("regex", "[a-z]+"));
        g.insert("alias_producer".to_string(), token("regex", "[a-z]+"));
        g.insert("forward_producer".to_string(), token("regex", "[a-z]+"));
        let order: Vec<String> = g.keys().cloned().collect();
        let mut generator = simple_generator(&g, &order, 1);
        // The store gate lives on `checked_type_identifier` (consults `type_name`), exactly as
        // `compute_reach_gate_kinds` records the SV `has_fact(type_name, …)` predicate.
        generator.reach_gate_kinds.insert(
            "checked_type_identifier".to_string(),
            vec!["type_name".to_string()],
        );
        // ALIAS host path (Or alternative 0, the producer at Sequence element 2): the off-path sibling
        // `class_type` (element 1) descends to the `type_name` gate, unsatisfiable in an empty store.
        let alias_hops = vec![("type_declaration".to_string(), "root/o0/s2".to_string())];
        assert!(
            generator.reach_path_renders_unsatisfiable_gate(&alias_hops),
            "the alias host branch crosses the mandatory class_type → has_fact(type_name) gate"
        );
        // FORWARD host path (Or alternative 1): off-path siblings are only literals — clean.
        let forward_hops = vec![("type_declaration".to_string(), "root/o1/s2".to_string())];
        assert!(
            !generator.reach_path_renders_unsatisfiable_gate(&forward_hops),
            "the forward host branch is clean (kw_class literal, no gated sibling)"
        );
    }

    #[test]
    fn multi_token_regex_terminal_tail_separates_from_following_keyword() {
        // GRAMMAR-WELLFORMED.H.11.1: a single regex terminal can render MULTI-TOKEN text whose
        // tail is a free word token (the vhdl `physical_literal` shape: number + whitespace +
        // unit, `8 min`). The recorded tail word-shape must be TAIL-aware so the join rule
        // separates that tail from a following word-shaped token — the whole-string check read
        // `"8 min"` as non-fusable and produced the parser-rejected fusion `8 minto`.
        let mut grammar_tree = HashMap::new();
        grammar_tree.insert(
            "s".to_string(),
            ASTNode::Sequence {
                elements: vec![rule_ref("lit"), rule_ref("kw")],
            },
        );
        grammar_tree.insert(
            "lit".to_string(),
            token("regex", "[0-9]+[ \\t]+(?:ms|ns)\\b"),
        );
        grammar_tree.insert("kw".to_string(), token("regex", "(?i:to)\\b"));
        let rule_order: Vec<String> = ["s", "lit", "kw"].iter().map(|s| s.to_string()).collect();
        let mut generator = StimuliGenerator::new(
            "g".to_string(),
            &grammar_tree,
            &rule_order,
            None,
            StimuliConfig {
                seed: Some(3),
                enforce_word_boundary_spacing: true,
                ..StimuliConfig::default()
            },
        );
        let out = generator
            .generate_from_entry("s")
            .expect("multi-token-terminal sequence generation should succeed");
        let re = Regex::new(r"^[0-9]+[ \t]+(?:ms|ns)\s+(?i:to)\s*$").expect("valid expectation");
        assert!(
            re.is_match(&out),
            "the multi-token terminal's word tail must be separated from the following keyword \
             (never `msto`/`minto`-style fusion): {out:?}"
        );
    }

    #[test]
    fn discarded_or_attempt_restores_word_shape_flags() {
        // GRAMMAR-WELLFORMED.H.11.2-FIX: the word-shape flag pair is TRANSACTIONAL across
        // discarded OR attempts. A failing branch renders a non-word partial (`.`) before it
        // fails; when the whole OR fails, the caller keeps none of its text, so the flags must
        // describe the tail as it was at OR entry — never the discarded partial's.
        let mut grammar_tree = HashMap::new();
        grammar_tree.insert(
            "alt".to_string(),
            ASTNode::Or {
                alternatives: vec![rule_ref("bad")],
            },
        );
        grammar_tree.insert(
            "bad".to_string(),
            ASTNode::Sequence {
                elements: vec![token("quoted_string", "."), rule_ref("bad")],
            },
        );
        let rule_order: Vec<String> = ["alt", "bad"].iter().map(|s| s.to_string()).collect();
        let mut generator = StimuliGenerator::new(
            "g".to_string(),
            &grammar_tree,
            &rule_order,
            None,
            StimuliConfig {
                seed: Some(1),
                enforce_word_boundary_spacing: true,
                ..StimuliConfig::default()
            },
        );
        generator.last_terminal_word_shaped = true;
        generator.last_terminal_from_atomic_rule = true;
        let result = generator.generate_from_entry("alt");
        assert!(result.is_err(), "the self-recursive branch must fail");
        assert!(
            generator.last_terminal_word_shaped && generator.last_terminal_from_atomic_rule,
            "a fully-discarded OR must restore the entry word-shape flag pair (stale loser flags \
             are the H.11.2-CLASS fusion bug)"
        );
    }

    #[test]
    fn discarded_quantified_candidate_restores_word_shape_flags() {
        // GRAMMAR-WELLFORMED.H.11.2-FIX: same transactional rule at the quantifier boundary —
        // a `+` whose body always fails discards every repeat-count candidate (each having
        // rendered a non-word `.` partial first) and must restore the entry pair on failure.
        let mut grammar_tree = HashMap::new();
        grammar_tree.insert(
            "q".to_string(),
            ASTNode::Quantified {
                element: Box::new(rule_ref("bad")),
                quantifier: "+".to_string(),
            },
        );
        grammar_tree.insert(
            "bad".to_string(),
            ASTNode::Sequence {
                elements: vec![token("quoted_string", "."), rule_ref("bad")],
            },
        );
        let rule_order: Vec<String> = ["q", "bad"].iter().map(|s| s.to_string()).collect();
        let mut generator = StimuliGenerator::new(
            "g".to_string(),
            &grammar_tree,
            &rule_order,
            None,
            StimuliConfig {
                seed: Some(1),
                enforce_word_boundary_spacing: true,
                ..StimuliConfig::default()
            },
        );
        generator.last_terminal_word_shaped = true;
        generator.last_terminal_from_atomic_rule = true;
        let result = generator.generate_from_entry("q");
        assert!(result.is_err(), "a `+` over an always-failing body must fail");
        assert!(
            generator.last_terminal_word_shaped && generator.last_terminal_from_atomic_rule,
            "a fully-discarded quantifier must restore the entry word-shape flag pair"
        );
    }

    #[test]
    fn discarded_quantifier_iteration_does_not_fuse_following_keyword() {
        // GRAMMAR-WELLFORMED.H.11.2-FIX end-to-end lock — THE dominant H.11.2-CLASS shape
        // (13 of 15 vhdl-sweep fusion sites): `name := word_id (dot bad)*` tries a repeat
        // count > 0, renders the non-word `.`, fails deeper, and keeps the EMPTY repeats=0
        // candidate — pre-fix the discarded `.`'s stale flags made the join rule skip the
        // separator before the following keyword (`xy`+`is` → `xyis`, parser-rejected).
        // Seed-swept so the lock holds regardless of which repeat count is preferred first.
        let mut grammar_tree = HashMap::new();
        grammar_tree.insert(
            "s".to_string(),
            ASTNode::Sequence {
                elements: vec![rule_ref("name"), rule_ref("kw")],
            },
        );
        grammar_tree.insert(
            "name".to_string(),
            ASTNode::Sequence {
                elements: vec![
                    rule_ref("word_id"),
                    ASTNode::Quantified {
                        element: Box::new(rule_ref("tail")),
                        quantifier: "*".to_string(),
                    },
                ],
            },
        );
        grammar_tree.insert(
            "tail".to_string(),
            ASTNode::Sequence {
                elements: vec![token("quoted_string", "."), rule_ref("bad")],
            },
        );
        grammar_tree.insert(
            "bad".to_string(),
            ASTNode::Sequence {
                elements: vec![token("quoted_string", "."), rule_ref("bad")],
            },
        );
        grammar_tree.insert("word_id".to_string(), token("regex", "[a-z]{2}"));
        grammar_tree.insert("kw".to_string(), token("regex", "(?i:is)\\b"));
        let rule_order: Vec<String> = ["s", "name", "tail", "bad", "word_id", "kw"]
            .iter()
            .map(|s| s.to_string())
            .collect();
        let expectation =
            Regex::new(r"^[a-z]{2}\s+(?i:is)\s*$").expect("valid expectation regex");
        for seed in 0..16u64 {
            let mut generator = StimuliGenerator::new(
                "g".to_string(),
                &grammar_tree,
                &rule_order,
                None,
                StimuliConfig {
                    seed: Some(seed),
                    enforce_word_boundary_spacing: true,
                    ..StimuliConfig::default()
                },
            );
            let out = generator
                .generate_from_entry("s")
                .expect("the repeats=0 candidate must let the sequence succeed");
            assert!(
                expectation.is_match(&out),
                "seed {seed}: the identifier tail must stay separated from the following \
                 keyword after a discarded quantifier iteration (never `xyis` fusion): {out:?}"
            );
        }
    }

    #[test]
    fn semantic_prelude_witnesses_count_gated_rule() {
        // GRAMMAR-WELLFORMED.C2.2: the end-to-end two-phase semantic-prelude flow on a
        // synthetic count-gated grammar (the regex store-gated pair's exact shape, no
        // grammar names): `gated := "#" two_digits` needs ≥ NN `producer` facts BEFORE
        // it, `two_digits` is two+ digits, so phase 1 captures the rendered value and
        // phase 2 injects exactly that many producer iterations at the on-path
        // quantifier site before replaying the captured render.
        let mut grammar_tree = HashMap::new();
        grammar_tree.insert(
            "start".to_string(),
            ASTNode::Quantified {
                element: Box::new(rule_ref("item")),
                quantifier: "+".to_string(),
            },
        );
        grammar_tree.insert(
            "item".to_string(),
            ASTNode::Or {
                alternatives: vec![rule_ref("producer"), rule_ref("gated")],
            },
        );
        grammar_tree.insert(
            "producer".to_string(),
            ASTNode::Sequence {
                elements: vec![token("string", "("), token("string", ")")],
            },
        );
        grammar_tree.insert(
            "gated".to_string(),
            ASTNode::Sequence {
                elements: vec![token("string", "#"), rule_ref("two_digits")],
            },
        );
        grammar_tree.insert("two_digits".to_string(), token("regex", "[1-9][0-9]"));
        let rule_order: Vec<String> = ["start", "item", "producer", "gated", "two_digits"]
            .iter()
            .map(|s| s.to_string())
            .collect();
        let mut generator = simple_generator(&grammar_tree, &rule_order, 7);
        generator.store_aware_gen = true;
        generator
            .gen_count_kinds
            .insert("gated".to_string(), vec!["grp".to_string()]);
        generator.gen_emit_facts.insert(
            "producer".to_string(),
            vec![SemanticFactSpec {
                kind: "grp".to_string(),
                name: crate::ast_pipeline::SemanticRuntimeValue::Identifier("g".to_string()),
                attributes: vec![],
            }],
        );

        let mut samples: Vec<String> = Vec::new();
        let report = generator.generate_plannable_rule_witnesses(
            "start",
            &["gated".to_string()],
            0,
            4,
            |_rule, sample| {
                samples.push(sample.to_string());
                // The stand-in "parser": the sample witnesses `gated` iff its `#NN`
                // reference is covered by ≥ NN preceding `()` producer units (the
                // same satisfaction shape as `fact_count_at_least`).
                let Some(hash) = sample.find('#') else {
                    return PlannableProbeVerdict::NotParsed;
                };
                let producers = sample[..hash].matches("()").count();
                let digits: String = sample[hash + 1..]
                    .chars()
                    .take_while(|c| c.is_ascii_digit())
                    .collect();
                match digits.parse::<usize>() {
                    Ok(value) if producers >= value => PlannableProbeVerdict::Witnessed,
                    _ => PlannableProbeVerdict::NotParsed,
                }
            },
        );

        assert_eq!(
            report.witnessed, 1,
            "the count-gated rule must be witnessed via the armed prelude; samples={samples:?}"
        );
        assert!(
            samples.len() >= 2,
            "phase 1 (capture) + phase 2 (armed) probes expected: {samples:?}"
        );
        let witnessing = samples.last().expect("at least one probe sample");
        let hash = witnessing
            .find('#')
            .expect("witnessing sample carries the gated render");
        let producers = witnessing[..hash].matches("()").count();
        let digits: String = witnessing[hash + 1..]
            .chars()
            .take_while(|c| c.is_ascii_digit())
            .collect();
        let value: usize = digits.parse().expect("two-digit reference");
        assert!(
            value >= 10,
            "the gated render is two digits by construction: {witnessing:?}"
        );
        assert_eq!(
            producers, value,
            "phase 2 must inject exactly `value` producer iterations before the gated render: {witnessing:?}"
        );
    }

    #[test]
    fn literal_threshold_count_prelude_arms_immediately() {
        // STORE-AWARE-GEN.4b.17: a LITERAL-threshold count gate (`fact_count_at_least(K, N)`, the SV
        // `wildcard_import_open, 1` shape on `wildcard_escape_nettype_identifier`) arms its prelude
        // IMMEDIATELY (`iterations = N`) — there is no generated `$ref` value to capture, so the gated
        // rule's render is a fixed marker, not a digit run. The prelude hosts N producer iterations from
        // the first attempt and the gated rule witnesses with no phase-1 capture probe. Synthetic shape:
        // `gated := "#"` needs ≥ 1 `producer` fact before it (a bare marker, like the wildcard's bare
        // escaped-id net-decl), `producer := "()"` emits the fact.
        let mut grammar_tree = HashMap::new();
        grammar_tree.insert(
            "start".to_string(),
            ASTNode::Quantified {
                element: Box::new(rule_ref("item")),
                quantifier: "+".to_string(),
            },
        );
        grammar_tree.insert(
            "item".to_string(),
            ASTNode::Or {
                alternatives: vec![rule_ref("producer"), rule_ref("gated")],
            },
        );
        grammar_tree.insert(
            "producer".to_string(),
            ASTNode::Sequence {
                elements: vec![token("string", "("), token("string", ")")],
            },
        );
        grammar_tree.insert("gated".to_string(), token("string", "#"));
        let rule_order: Vec<String> = ["start", "item", "producer", "gated"]
            .iter()
            .map(|s| s.to_string())
            .collect();
        let mut generator = simple_generator(&grammar_tree, &rule_order, 7);
        generator.store_aware_gen = true;
        generator
            .gen_count_kinds
            .insert("gated".to_string(), vec!["grp".to_string()]);
        // The literal threshold N = 1 — arm the prelude immediately (no `$ref` capture).
        generator
            .gen_count_literal_thresholds
            .insert("gated".to_string(), 1);
        generator.gen_emit_facts.insert(
            "producer".to_string(),
            vec![SemanticFactSpec {
                kind: "grp".to_string(),
                name: crate::ast_pipeline::SemanticRuntimeValue::Identifier("g".to_string()),
                attributes: vec![],
            }],
        );

        let mut samples: Vec<String> = Vec::new();
        let report = generator.generate_plannable_rule_witnesses(
            "start",
            &["gated".to_string()],
            0,
            4,
            |_rule, sample| {
                samples.push(sample.to_string());
                // The stand-in "parser": `gated` (`#`) is witnessed iff ≥ 1 `()` producer precedes it
                // (the `fact_count_at_least(K, 1)` satisfaction shape).
                let Some(hash) = sample.find('#') else {
                    return PlannableProbeVerdict::NotParsed;
                };
                if sample[..hash].matches("()").count() >= 1 {
                    PlannableProbeVerdict::Witnessed
                } else {
                    PlannableProbeVerdict::NotParsed
                }
            },
        );

        assert_eq!(
            report.witnessed, 1,
            "a literal-threshold count gate must be witnessed via the immediately-armed prelude; samples={samples:?}"
        );
        let witnessing = samples
            .iter()
            .find(|s| s.find('#').is_some_and(|h| s[..h].matches("()").count() >= 1))
            .expect("a witnessing sample with a producer before the gated marker");
        let hash = witnessing.find('#').expect("gated marker present");
        assert!(
            witnessing[..hash].matches("()").count() >= 1,
            "the immediately-armed prelude must inject ≥ 1 producer before the gated render: {witnessing:?}"
        );
    }

    #[test]
    fn gen_count_predicate_satisfiable_honors_literal_threshold() {
        // STORE-AWARE-GEN.4b.17: the `.3` count==0 prune is N-EXACT for a literal-threshold gate. A rule
        // gated `fact_count_at_least(K, 2)` is unsatisfiable until ≥ 2 `K` facts exist; a `$ref`-gated
        // rule (absent from `gen_count_literal_thresholds`) defaults to threshold 1 — byte-identical to
        // the prior hard-coded value.
        let mut grammar_tree = HashMap::new();
        grammar_tree.insert("start".to_string(), token("quoted_string", "x"));
        let rule_order = vec!["start".to_string()];
        let mut generator = simple_generator(&grammar_tree, &rule_order, 1);
        generator.store_aware_gen = true;
        generator
            .gen_count_kinds
            .insert("two_imports".to_string(), vec!["imp".to_string()]);
        generator
            .gen_count_literal_thresholds
            .insert("two_imports".to_string(), 2);
        // `$ref`-style rule: no literal threshold ⇒ defaults to 1.
        generator
            .gen_count_kinds
            .insert("backref".to_string(), vec!["grp".to_string()]);

        let emit = |generator: &mut StimuliGenerator, kind: &str| {
            generator.gen_semantic_state.emit_fact(SemanticFactSpec {
                kind: kind.to_string(),
                name: crate::ast_pipeline::SemanticRuntimeValue::Identifier("n".to_string()),
                attributes: vec![],
            });
        };

        assert!(
            !generator.gen_count_predicate_satisfiable("two_imports"),
            "zero `imp` facts < threshold 2 ⇒ unsatisfiable"
        );
        emit(&mut generator, "imp");
        assert!(
            !generator.gen_count_predicate_satisfiable("two_imports"),
            "one `imp` fact < threshold 2 ⇒ still unsatisfiable (N-exact)"
        );
        emit(&mut generator, "imp");
        assert!(
            generator.gen_count_predicate_satisfiable("two_imports"),
            "two `imp` facts >= threshold 2 ⇒ satisfiable"
        );
        // The `$ref` default-1 path is unchanged: one `grp` fact suffices.
        emit(&mut generator, "grp");
        assert!(
            generator.gen_count_predicate_satisfiable("backref"),
            "a `$ref`-gated rule defaults to threshold 1 ⇒ one fact suffices (byte-identical)"
        );
    }

