    #[test]
    fn literal_hint_renders_keep_word_boundary_separation_between_items() {
        // GRAMMAR-WELLFORMED.H.8 (Defect A): two consecutive items each rendered via a
        // rule-level `@sample` literal override must not fuse their boundary keywords
        // (`endprogram`+`program` → `endprogramprogram`); the hint render must record its
        // tail word-shape so the concat join rule inserts the separating space.
        let mut grammar_tree = HashMap::new();
        grammar_tree.insert(
            "start".to_string(),
            ASTNode::Sequence {
                elements: vec![
                    token("rule_reference", "item"),
                    token("rule_reference", "item"),
                ],
            },
        );
        grammar_tree.insert("item".to_string(), token("quoted_string", "fallback"));
        let rule_order = vec!["start".to_string(), "item".to_string()];

        let mut annotations = Annotations::default();
        annotations.semantic_annotations.insert(
            "item".to_string(),
            vec![SemanticAnnotation::Named {
                name: "sample".to_string(),
                ast: UnifiedSemanticAST::Structured {
                    canonical: "\"program p; endprogram\"".to_string(),
                    value: UnifiedSemanticValue::String("program p; endprogram".to_string()),
                },
            }],
        );

        // Faithfulness ON (the shipped default) — `annotated_generator` opts out of it, but the
        // word-boundary join rule under test only runs with spacing enforced.
        let mut generator = StimuliGenerator::new(
            "test".to_string(),
            &grammar_tree,
            &rule_order,
            Some(&annotations),
            StimuliConfig {
                seed: Some(4242),
                max_depth: 8,
                enforce_word_boundary_spacing: true,
                ..StimuliConfig::default()
            },
        );
        let values = generator
            .generate_many(1, Some("start"))
            .expect("hint-driven generation should succeed");
        assert_eq!(
            values[0], "program p; endprogram program p; endprogram",
            "adjacent literal-hint renders must keep a word-boundary separator (Defect A)"
        );
    }

    #[test]
    fn literal_hint_tail_word_shape_classification() {
        // Free tail tokens (fusable — a following word char needs a separator):
        assert!(StimuliGenerator::tail_word_shaped("endprogram"));
        assert!(StimuliGenerator::tail_word_shaped(
            "program p; endprogram"
        ));
        assert!(StimuliGenerator::tail_word_shaped(
            "output o, input i"
        ));
        // Non-word tails (nothing to fuse):
        assert!(!StimuliGenerator::tail_word_shaped("wire a;"));
        assert!(!StimuliGenerator::tail_word_shaped(" //"));
        assert!(!StimuliGenerator::tail_word_shaped(""));
        // A word-run glued to a structural char is a literal fragment, not a free token
        // (the `(?(R` convention — it must stay adjacent to its argument):
        assert!(!StimuliGenerator::tail_word_shaped("(?(R"));
    }

    #[test]
    fn quantifier_sites_along_path_extracts_each_q_crossing() {
        // GRAMMAR-WELLFORMED.H.7.2: one site per `q` segment, at the prefix BEFORE it
        // (the Quantified node's own path — what `generate_quantified` receives).
        assert_eq!(
            StimuliGenerator::quantifier_sites_along_path("r", "root/s1/q/s0/a"),
            vec![("r".to_string(), "root/s1".to_string())]
        );
        assert_eq!(
            StimuliGenerator::quantifier_sites_along_path("r", "root/s1/q/s2/q/a"),
            vec![
                ("r".to_string(), "root/s1".to_string()),
                ("r".to_string(), "root/s1/q/s2".to_string()),
            ]
        );
        assert!(StimuliGenerator::quantifier_sites_along_path("r", "root/s0/o1/a").is_empty());
    }

    #[test]
    fn target_own_reach_sites_finds_root_or_and_inner_optionals() {
        // GRAMMAR-WELLFORMED.H.12.5.5.3.2 (M1b): the target-own walker — purely structural, NO parser
        // dependency. It reports a rule's TOP-LEVEL choice (the spine `Or`, descending through
        // `Atom::Node` grouping shells only) and every min-0 (`?`/`*`) quantifier node-path inside the
        // body, in the SAME `o{i}`/`s{i}`/`q`/`a` encoding `generate_or`/`generate_quantified` receive.
        let mut grammar_tree: HashMap<String, ASTNode> = HashMap::new();
        // B-i: a direct root `Or` of 3 alternatives, no optionals.
        grammar_tree.insert(
            "bi_target".to_string(),
            ASTNode::Or {
                alternatives: vec![
                    rule_ref("pass_through"),
                    ASTNode::Sequence {
                        elements: vec![token("quoted_string", "kw"), rule_ref("distinct")],
                    },
                    token("quoted_string", "lit"),
                ],
            },
        );
        // Atom::Node(Or) grouping shell: the spine descends one `/a` before reaching the `Or`.
        grammar_tree.insert(
            "shelled_target".to_string(),
            ASTNode::Atom {
                value: ASTValue::Node(Box::new(ASTNode::Or {
                    alternatives: vec![token("quoted_string", "x"), token("quoted_string", "y")],
                })),
            },
        );
        // B-ii: a Sequence (NO top-level choice) whose distinguishing token sits behind a `?`, plus a
        // nested `*` inside an alternation, to exercise the path encoding through `s`/`o` segments.
        grammar_tree.insert(
            "bii_target".to_string(),
            ASTNode::Sequence {
                elements: vec![
                    token("quoted_string", "lead"),
                    ASTNode::Quantified {
                        element: Box::new(rule_ref("opt_a")),
                        quantifier: "?".to_string(),
                    },
                    ASTNode::Or {
                        alternatives: vec![
                            ASTNode::Quantified {
                                element: Box::new(rule_ref("opt_b")),
                                quantifier: "*".to_string(),
                            },
                            token("quoted_string", "z"),
                        ],
                    },
                ],
            },
        );
        let rule_order = vec![
            "bi_target".to_string(),
            "shelled_target".to_string(),
            "bii_target".to_string(),
        ];
        let generator = simple_generator(&grammar_tree, &rule_order, 0);

        // B-i: root `Or` at "root" with 3 alternatives; no optionals to force.
        let (root_or, inner) = generator.target_own_reach_sites("bi_target");
        assert_eq!(root_or, Some(("root".to_string(), 3)));
        assert!(inner.is_empty(), "no `?`/`*` in bi_target, got {:?}", inner);

        // Atom::Node(Or) shell: the spine `Or` is at "root/a".
        let (root_or, inner) = generator.target_own_reach_sites("shelled_target");
        assert_eq!(root_or, Some(("root/a".to_string(), 2)));
        assert!(inner.is_empty());

        // B-ii: NO top-level choice; the `?` is at "root/s1" and the nested `*` at "root/s2/o0".
        let (root_or, inner) = generator.target_own_reach_sites("bii_target");
        assert_eq!(root_or, None);
        assert_eq!(inner, vec!["root/s1".to_string(), "root/s2/o0".to_string()]);

        // A rule absent from the tree yields nothing (defensive).
        let (root_or, inner) = generator.target_own_reach_sites("missing");
        assert_eq!(root_or, None);
        assert!(inner.is_empty());
    }

    #[test]
    fn mandatory_child_rules_follows_mandatory_refs_only() {
        // GRAMMAR-WELLFORMED.H.12.5.5.3.3.1 (C-ii): the mandatory-child walker collects rule
        // references reached through MANDATORY positions only — Sequence elements, min-1
        // (`+`/`{N,…}`) quantifier groups, and `Atom::Node` grouping shells — and SKIPS min-0
        // quantifiers (`?`/`*`), un-forced `Or` alternatives, lookaheads, and self-recursion.
        // Order-preserving + deduped.
        let mut grammar_tree: HashMap<String, ASTNode> = HashMap::new();
        grammar_tree.insert(
            "carrier".to_string(),
            ASTNode::Sequence {
                elements: vec![
                    rule_ref("mand_a"), // mandatory (Sequence element)
                    ASTNode::Quantified {
                        // min-0 ⇒ skip
                        element: Box::new(rule_ref("opt_skip")),
                        quantifier: "?".to_string(),
                    },
                    ASTNode::Quantified {
                        // min-1 ⇒ mandatory; its body's refs are collected
                        element: Box::new(ASTNode::Sequence {
                            elements: vec![rule_ref("mand_b"), rule_ref("mand_a")], // mand_a dup
                        }),
                        quantifier: "+".to_string(),
                    },
                    ASTNode::Or {
                        // un-forced choice ⇒ skip both arms
                        alternatives: vec![rule_ref("or_skip_1"), rule_ref("or_skip_2")],
                    },
                    ASTNode::Lookahead {
                        // materialises nothing ⇒ skip
                        element: Box::new(rule_ref("la_skip")),
                        positive: true,
                    },
                    ASTNode::Atom {
                        // grouping shell ⇒ descend
                        value: ASTValue::Node(Box::new(rule_ref("mand_c"))),
                    },
                    rule_ref("carrier"), // self-recursion ⇒ skip
                ],
            },
        );
        let rule_order = vec!["carrier".to_string()];
        let generator = simple_generator(&grammar_tree, &rule_order, 0);

        // Body order, deduped; optionals / Or arms / lookahead / self all skipped.
        assert_eq!(
            generator.mandatory_child_rules("carrier"),
            vec![
                "mand_a".to_string(),
                "mand_b".to_string(),
                "mand_c".to_string(),
            ]
        );
        // A rule absent from the tree yields nothing (defensive).
        assert!(generator.mandatory_child_rules("missing").is_empty());
    }

    #[test]
    fn plannable_rule_witness_reaches_optional_gated_rule() {
        // GRAMMAR-WELLFORMED.H.7.2 end-to-end: the svpp `macro_default_text` shape in
        // miniature — the target rule sits behind TWO un-taken optionals. Minimal
        // (construct-mode) generation expands `?` to zero, so only the plan's forced
        // quantifier expansion can descend to the target.
        let mut grammar_tree = HashMap::new();
        grammar_tree.insert(
            "start".to_string(),
            ASTNode::Sequence {
                elements: vec![
                    token("quoted_string", "a"),
                    ASTNode::Quantified {
                        element: Box::new(token("rule_reference", "tail")),
                        quantifier: "?".to_string(),
                    },
                ],
            },
        );
        grammar_tree.insert(
            "tail".to_string(),
            ASTNode::Sequence {
                elements: vec![
                    token("quoted_string", "t"),
                    ASTNode::Quantified {
                        element: Box::new(token("rule_reference", "inner")),
                        quantifier: "?".to_string(),
                    },
                ],
            },
        );
        grammar_tree.insert(
            "inner".to_string(),
            ASTNode::Or {
                alternatives: vec![token("quoted_string", "i"), token("quoted_string", "j")],
            },
        );
        let rule_order = vec!["start".to_string(), "tail".to_string(), "inner".to_string()];
        let mut generator = simple_generator(&grammar_tree, &rule_order, 7);

        // The "parser" here is a textual stand-in: a sample witnesses `inner` iff the
        // optional-gated chain was actually descended ("a" then "t" then "i"|"j").
        let mut probe_samples: Vec<String> = Vec::new();
        let report = generator.generate_plannable_rule_witnesses(
            "start",
            &["inner".to_string()],
            0,
            4,
            |_rule, sample| {
                probe_samples.push(sample.to_string());
                if sample.contains('t') && (sample.contains('i') || sample.contains('j')) {
                    PlannableProbeVerdict::Witnessed
                } else {
                    PlannableProbeVerdict::ParsedNotWitnessed
                }
            },
        );
        assert_eq!(report.attempted, 1);
        assert!(report.no_path.is_empty(), "inner IS graph-reachable: {:?}", report);
        assert_eq!(
            report.witnessed, 1,
            "plan-forced construct generation must witness the optional-gated chain; probes={:?}",
            probe_samples
        );

        // And a rule that exists but is referenced nowhere has NO path — reported, not guessed.
        grammar_tree.insert("orphan".to_string(), token("quoted_string", "x"));
        let rule_order = vec![
            "start".to_string(),
            "tail".to_string(),
            "inner".to_string(),
            "orphan".to_string(),
        ];
        let mut generator = simple_generator(&grammar_tree, &rule_order, 7);
        let report = generator.generate_plannable_rule_witnesses(
            "start",
            &["orphan".to_string()],
            0,
            4,
            |_rule, _sample| PlannableProbeVerdict::Witnessed,
        );
        assert_eq!(
            report.no_path,
            vec!["orphan".to_string()],
            "orphan must report no_path"
        );
        assert_eq!(report.attempted, 0);
    }

    #[test]
    fn min_full_derivation_depth_increases_along_a_rule_chain() {
        // RTL-FE-CLOSURE.5.2: the depth fixpoint that sizes the per-target witness budget
        // must grow with derivation depth — a longer mandatory rule chain yields a strictly
        // larger minimal-derivation depth — and an `Or` takes the SHALLOWEST resolvable
        // alternative (so a choice between a shallow and a deep branch is governed by the
        // shallow one).
        let mut grammar_tree = HashMap::new();
        grammar_tree.insert("leaf".to_string(), token("quoted_string", "x"));
        grammar_tree.insert("mid".to_string(), token("rule_reference", "leaf"));
        grammar_tree.insert("top".to_string(), token("rule_reference", "mid"));
        grammar_tree.insert(
            "choice".to_string(),
            ASTNode::Or {
                alternatives: vec![
                    token("rule_reference", "leaf"),
                    token("rule_reference", "top"),
                ],
            },
        );
        let rule_order = vec![
            "leaf".to_string(),
            "mid".to_string(),
            "top".to_string(),
            "choice".to_string(),
        ];
        let generator = simple_generator(&grammar_tree, &rule_order, 1);
        let depths = generator.compute_min_full_derivation_depths();
        assert!(
            depths["leaf"] < depths["mid"] && depths["mid"] < depths["top"],
            "minimal-derivation depth must grow along the chain: {:?}",
            depths
        );
        // The `Or` resolves through its shallowest branch (`leaf`), so it never exceeds the
        // deep branch (`top`) — the witness budget is governed by the shallowest derivation.
        assert!(
            depths["choice"] <= depths["top"],
            "Or picks the shallowest branch: choice={} top={}",
            depths["choice"],
            depths["top"]
        );
    }

    #[test]
    fn witness_store_entry_blocked_verdict_is_closure_branch_and_polarity_scoped() {
        // SV-EXH-PROOF.7.4.6.12: the witness pass raises its entry for a target whose MANDATORY
        // POSITIVE store gate consults a kind no rule in the target's OWN closure can emit. This
        // pins all four claims the verdict rests on, each with its own negative control, on a
        // synthetic grammar (no grammar identifiers, no SystemVerilog dependency):
        //     producer   := "p"                     @emit_fact { kind: k }
        //     gated      := "g"                     @predicate fact_count_at_least(k, 1)
        //     plain      := "x"
        //     carrier    := plain | gated           (branch 0 is a clean escape)
        //     self_fed   := producer gated          (the emitter is INSIDE the closure)
        //     negated    := "n"                     a NEGATIVE gate only
        let mut g = HashMap::new();
        g.insert("producer".to_string(), token("quoted_string", "p"));
        g.insert("gated".to_string(), token("quoted_string", "g"));
        g.insert("plain".to_string(), token("quoted_string", "x"));
        g.insert(
            "carrier".to_string(),
            ASTNode::Or {
                alternatives: vec![rule_ref("plain"), rule_ref("gated")],
            },
        );
        g.insert(
            "self_fed".to_string(),
            ASTNode::Sequence {
                elements: vec![rule_ref("producer"), rule_ref("gated")],
            },
        );
        g.insert("negated".to_string(), token("quoted_string", "n"));
        let order: Vec<String> = vec![
            "producer".to_string(),
            "gated".to_string(),
            "plain".to_string(),
            "carrier".to_string(),
            "self_fed".to_string(),
            "negated".to_string(),
        ];
        let mut generator = simple_generator(&g, &order, 1);
        generator
            .gen_count_kinds
            .insert("gated".to_string(), vec!["k".to_string()]);
        generator.gen_emit_facts.insert(
            "producer".to_string(),
            vec![SemanticFactSpec {
                kind: "k".to_string(),
                name: SemanticRuntimeValue::RuleReference("body".to_string()),
                attributes: vec![],
            }],
        );
        // `negated` is store-gated ONLY negatively — visible to the reach-BFS gate map, absent
        // from both positive maps, exactly as `compute_reach_gate_kinds` vs `compute_name_gates`
        // classify a `lacks_fact` predicate.
        generator
            .reach_gate_kinds
            .insert("negated".to_string(), vec!["k".to_string()]);

        let status = |rule: &str, target_type, node_path: Option<&str>, branch_index| {
            TargetCoverageStatus {
                id: format!("t::{}", rule),
                target_type,
                rule_name: rule.to_string(),
                node_path: node_path.map(str::to_string),
                branch_index,
                current_successes: 0,
                required_successes: 1,
                remaining_successes: 1,
                priority_score: 0,
                reason: String::new(),
                depends_on: Vec::new(),
            }
        };

        // (1) THE DEFECT: a rule whose whole body is gated on a kind nothing in its own closure
        //     emits is unwitnessable from its own entry at ANY budget — raise the entry.
        assert!(
            generator.witness_target_is_store_entry_blocked(&status(
                "gated",
                StimuliCoverageTargetType::Rule,
                None,
                None
            )),
            "a rule gated on a kind its own closure cannot emit is store-entry-blocked"
        );
        // (2) CLOSURE CONTROL: the SAME gate, but with the emitter inside the target's closure, is
        //     NOT blocked — so the verdict is genuinely about the closure, not about the gate.
        assert!(
            !generator.witness_target_is_store_entry_blocked(&status(
                "self_fed",
                StimuliCoverageTargetType::Rule,
                None,
                None
            )),
            "an in-closure emitter makes the same gate satisfiable — no raise"
        );
        // (3) MANDATORY CONTROL: a rule whose root `Or` offers an ungated escape is not blocked,
        //     because the generator can simply take the escape.
        assert!(
            !generator.witness_target_is_store_entry_blocked(&status(
                "carrier",
                StimuliCoverageTargetType::Rule,
                None,
                None
            )),
            "an ungated escape alternative means the rule is not mandatorily gated"
        );
        // (4) BRANCH SCOPING: the gate that the whole-rule walk in (3) could not see IS seen once
        //     the target names the alternative — and only for that alternative.
        assert!(
            generator.witness_target_is_store_entry_blocked(&status(
                "carrier",
                StimuliCoverageTargetType::Branch,
                Some("root"),
                Some(1)
            )),
            "a branch target is judged on its TARGETED alternative, which is gated"
        );
        assert!(
            !generator.witness_target_is_store_entry_blocked(&status(
                "carrier",
                StimuliCoverageTargetType::Branch,
                Some("root"),
                Some(0)
            )),
            "the sibling escape alternative is not blocked"
        );
        // (5) POLARITY: a NEGATIVE gate is satisfied by the empty store a standalone witness starts
        //     with, so it must never trigger a raise — while the reach-BFS scope, which counts every
        //     fact query, does see it. Both scopes asserted, so the distinction cannot rot silently.
        let empty: HashSet<String> = HashSet::new();
        let mut visited: HashSet<String> = HashSet::new();
        assert!(
            generator.mandatory_reach_gate("negated", &empty, &mut visited, StoreGateScope::AnyQuery),
            "control: the reach-BFS scope counts a negative gate"
        );
        assert!(
            !generator.witness_target_is_store_entry_blocked(&status(
                "negated",
                StimuliCoverageTargetType::Rule,
                None,
                None
            )),
            "a lacks_fact-only gate must NOT raise the entry — the empty store satisfies it"
        );
    }

    #[test]
    fn witness_target_depth_budget_is_branch_scoped_not_rule_scoped() {
        // SV-EXH-PROOF.7.4.6.9: the closed-loop witness pass budgets a BRANCH target by THAT
        // BRANCH'S own minimal derivation depth, not by its rule's. The `.5.2` rule-scoped
        // formula reads the rule's SHALLOWEST alternative — precisely the alternative a
        // residual branch target is not — which is why it under-budgets a CONTAINER rule with
        // a shallow minimum and a deep residual branch (measured: three of the 40 class-A
        // targets need 52-54 and would get 47-50). This is that shape in miniature:
        // `container := leaf | top`, where `top` descends a mandatory rule chain.
        let mut grammar_tree = HashMap::new();
        grammar_tree.insert("leaf".to_string(), token("quoted_string", "x"));
        grammar_tree.insert("mid".to_string(), token("rule_reference", "leaf"));
        grammar_tree.insert("top".to_string(), token("rule_reference", "mid"));
        grammar_tree.insert(
            "container".to_string(),
            ASTNode::Or {
                alternatives: vec![
                    token("rule_reference", "leaf"),
                    token("rule_reference", "top"),
                ],
            },
        );
        let rule_order = vec![
            "leaf".to_string(),
            "mid".to_string(),
            "top".to_string(),
            "container".to_string(),
        ];
        let generator = simple_generator(&grammar_tree, &rule_order, 1);
        let depths = generator.compute_min_full_derivation_depths();
        let reach_prefix = 40usize;

        let status = |target_type, node_path: Option<&str>, branch_index| TargetCoverageStatus {
            id: "t".to_string(),
            target_type,
            rule_name: "container".to_string(),
            node_path: node_path.map(str::to_string),
            branch_index,
            current_successes: 0,
            required_successes: 1,
            remaining_successes: 1,
            priority_score: 0,
            reason: String::new(),
            depends_on: Vec::new(),
        };

        let rule_budget = generator.witness_target_depth_budget(
            &status(StimuliCoverageTargetType::Rule, None, None),
            reach_prefix,
            &depths,
        );
        let shallow_branch_budget = generator.witness_target_depth_budget(
            &status(StimuliCoverageTargetType::Branch, Some("root"), Some(0)),
            reach_prefix,
            &depths,
        );
        let deep_branch_budget = generator.witness_target_depth_budget(
            &status(StimuliCoverageTargetType::Branch, Some("root"), Some(1)),
            reach_prefix,
            &depths,
        );

        // The defect, and the fix: the DEEP branch gets strictly more budget than the
        // rule-scoped formula would have given it.
        assert!(
            deep_branch_budget > rule_budget,
            "deep branch must out-budget the rule-scoped formula: deep={} rule={}",
            deep_branch_budget,
            rule_budget
        );
        // …and it is exactly the branch's own subtree depth plus the `Or` site's own level.
        assert_eq!(
            deep_branch_budget,
            reach_prefix + depths["top"] + 1 + 1,
            "deep branch budget = reach_prefix + depth(top-reference) + Or level"
        );
        // MONOTONE: no target is ever budgeted BELOW the flat `reach_prefix` the pass used
        // before this slice, so a target that witnessed then still witnesses now.
        for budget in [rule_budget, shallow_branch_budget, deep_branch_budget] {
            assert!(
                budget >= reach_prefix,
                "per-target budget must never fall below the flat reach prefix: {} < {}",
                budget,
                reach_prefix
            );
        }
        // A branch whose alternative cannot be located falls back to the rule-scoped formula
        // rather than losing the addend entirely.
        assert_eq!(
            generator.witness_target_depth_budget(
                &status(StimuliCoverageTargetType::Branch, Some("root/s9"), Some(1)),
                reach_prefix,
                &depths,
            ),
            rule_budget,
            "an unresolvable branch path falls back to the rule-scoped budget"
        );
    }

    #[test]
    fn plannable_witness_reaches_target_behind_deep_mandatory_chain() {
        // RTL-FE-CLOSURE.5.2 end-to-end (the generate_if/rtl_expr shape in miniature): a
        // target sits behind an OR branch (force-entry) whose subtree is a deep MANDATORY
        // rule chain. Under the OLD fixed `original_max_depth * 2` witness budget the chain
        // overflows the depth limit, the forced branch aborts with depth-exceeded, and
        // generation falls back to the shallow sibling — so the target is NEVER witnessed.
        // The per-target budget (`original * 2 + min-derivation-depth[target]`) gives the
        // mandatory chain room, so the target witnesses. With `simple_generator`'s
        // `max_depth = 8` the doubled budget is 16; a 14-rule chain needs ~30 depth, so this
        // test fails if the budget regresses to the fixed `* 2`.
        let mut grammar_tree = HashMap::new();
        grammar_tree.insert("start".to_string(), token("rule_reference", "item"));
        grammar_tree.insert(
            "item".to_string(),
            ASTNode::Or {
                alternatives: vec![
                    token("rule_reference", "cheap"),
                    token("rule_reference", "deep_target"),
                ],
            },
        );
        grammar_tree.insert("cheap".to_string(), token("quoted_string", "c"));
        grammar_tree.insert(
            "deep_target".to_string(),
            ASTNode::Sequence {
                elements: vec![token("quoted_string", "t"), token("rule_reference", "c0")],
            },
        );
        let chain_len = 14;
        let mut rule_order = vec![
            "start".to_string(),
            "item".to_string(),
            "cheap".to_string(),
            "deep_target".to_string(),
        ];
        for i in 0..chain_len {
            let name = format!("c{}", i);
            let body = if i + 1 < chain_len {
                token("rule_reference", &format!("c{}", i + 1))
            } else {
                token("quoted_string", "x")
            };
            grammar_tree.insert(name.clone(), body);
            rule_order.push(name);
        }
        let mut generator = simple_generator(&grammar_tree, &rule_order, 7);
        let mut probes: Vec<String> = Vec::new();
        let report = generator.generate_plannable_rule_witnesses(
            "start",
            &["deep_target".to_string()],
            0,
            4,
            |_rule, sample| {
                probes.push(sample.to_string());
                if sample.contains('t') {
                    PlannableProbeVerdict::Witnessed
                } else {
                    PlannableProbeVerdict::ParsedNotWitnessed
                }
            },
        );
        assert_eq!(
            report.attempted, 1,
            "deep_target is graph-reachable: {:?}",
            report
        );
        assert_eq!(
            report.witnessed, 1,
            "per-target depth budget must reach the target behind the deep mandatory chain; probes={:?}",
            probes
        );
    }

    #[test]
    fn plannable_witness_reaches_target_with_deep_off_path_mandatory_sibling() {
        // RTL-FE-CLOSURE.5.5 end-to-end (the `event_control_item := event_edge? rtl_expr` shape
        // in miniature): a SHALLOW target sits behind an OPTIONAL element whose Sequence SIBLING
        // is a deep MANDATORY rule chain. `.5.2`'s budget (`reach_prefix + min_subtree[target]`)
        // does not see that sibling — the target's own subtree is tiny — so the mandatory chain
        // overflows the depth limit, the forced construct fails, and the target is NEVER
        // witnessed. `.5.5`'s budget (`reach_prefix + max(min_subtree[target],
        // max_offpath_mandatory_sibling_depth(target))`) fits the sibling, so it witnesses.
        // Distinct from `plannable_witness_reaches_target_behind_deep_mandatory_chain` (where the
        // deep chain is the target's OWN subtree, which `.5.2` already budgets).
        let mut grammar_tree = HashMap::new();
        grammar_tree.insert("start".to_string(), token("rule_reference", "host"));
        // host := edge? deep_sibling — `edge?` is the optional element on the path to the target;
        // the mandatory `deep_sibling` is the OFF-PATH sibling the construct must also derive.
        grammar_tree.insert(
            "host".to_string(),
            ASTNode::Sequence {
                elements: vec![
                    ASTNode::Quantified {
                        element: Box::new(token("rule_reference", "edge")),
                        quantifier: "?".to_string(),
                    },
                    token("rule_reference", "deep_sibling"),
                ],
            },
        );
        grammar_tree.insert("edge".to_string(), token("quoted_string", "t"));
        grammar_tree.insert("deep_sibling".to_string(), token("rule_reference", "c0"));
        let chain_len = 20;
        let mut rule_order = vec![
            "start".to_string(),
            "host".to_string(),
            "edge".to_string(),
            "deep_sibling".to_string(),
        ];
        for i in 0..chain_len {
            let name = format!("c{}", i);
            let body = if i + 1 < chain_len {
                token("rule_reference", &format!("c{}", i + 1))
            } else {
                token("quoted_string", "x")
            };
            grammar_tree.insert(name.clone(), body);
            rule_order.push(name);
        }
        // simple_generator's max_depth doubles to a budget that comfortably covers the deep chain
        // ONLY through the off-path sibling term — `min_subtree[edge]` alone is ~2.
        let mut generator = simple_generator(&grammar_tree, &rule_order, 7);
        let mut probes: Vec<String> = Vec::new();
        let report = generator.generate_plannable_rule_witnesses(
            "start",
            &["edge".to_string()],
            0,
            4,
            |_rule, sample| {
                probes.push(sample.to_string());
                if sample.contains('t') {
                    PlannableProbeVerdict::Witnessed
                } else {
                    PlannableProbeVerdict::ParsedNotWitnessed
                }
            },
        );
        assert_eq!(report.attempted, 1, "edge is graph-reachable: {:?}", report);
        assert_eq!(
            report.witnessed, 1,
            "off-path mandatory-sibling depth budget must reach the shallow target whose Sequence \
             sibling is a deep mandatory chain; probes={:?}",
            probes
        );
    }

    #[test]
    fn plannable_witness_reaches_self_recursive_forced_operator() {
        // RTL-FE-CLOSURE.5.6 (PGEN-RTL-FE-CLOSURE-0013) end-to-end (the
        // `unary_expr := bang unary_expr | … | primary_expr` shape in miniature): the reach plan
        // forces `unary := op unary | leaf` to its SELF-RECURSIVE operator branch (o0) to witness
        // `op`. Selecting it descends into the operand, which RE-ENTERS `unary` at the SAME
        // `(rule, node_path)` site. WITHOUT the .5.6 suppression the directive re-fires, forcing
        // `op` again and again — the operand never terminates minimally, so the only sample the
        // construct can yield is a runaway `!!!!!!x` (the recovery only finds `leaf` once the visit
        // budget is exhausted at the bottom), which witnesses NOTHING clean. WITH the suppression
        // the directive fires ONCE on the shallow entry and the re-entered operand falls to its
        // minimal terminating alternative (`leaf`), so the construct yields the bounded witness
        // `!x`. The witness check models the real cert-coverage judge: a clean operator render
        // (`op` present, no runaway `!!`) witnesses; a runaway does not. This test fails if the
        // suppression regresses (the recursion re-appears and only `!!…` is produced).
        let mut grammar_tree = HashMap::new();
        grammar_tree.insert("start".to_string(), token("rule_reference", "unary"));
        grammar_tree.insert(
            "unary".to_string(),
            ASTNode::Or {
                alternatives: vec![
                    // o0: SELF-RECURSIVE operator branch (the `bang unary_expr` shape) — the operand
                    // re-references `unary`, so the directive keyed on `(unary, root)` would re-fire.
                    ASTNode::Sequence {
                        elements: vec![
                            token("rule_reference", "op"),
                            token("rule_reference", "unary"),
                        ],
                    },
                    // o1: the only non-recursive terminating alternative (the minimal operand).
                    token("rule_reference", "leaf"),
                ],
            },
        );
        grammar_tree.insert("op".to_string(), token("quoted_string", "!"));
        grammar_tree.insert("leaf".to_string(), token("quoted_string", "x"));
        let rule_order = vec![
            "start".to_string(),
            "unary".to_string(),
            "op".to_string(),
            "leaf".to_string(),
        ];
        let mut generator = simple_generator(&grammar_tree, &rule_order, 7);
        let mut probes: Vec<String> = Vec::new();
        let report = generator.generate_plannable_rule_witnesses(
            "start",
            &["op".to_string()],
            0,
            4,
            |_rule, sample| {
                probes.push(sample.to_string());
                if sample.contains('!') && !sample.contains("!!") {
                    PlannableProbeVerdict::Witnessed
                } else {
                    PlannableProbeVerdict::ParsedNotWitnessed
                }
            },
        );
        assert_eq!(report.attempted, 1, "op is graph-reachable: {:?}", report);
        assert_eq!(
            report.witnessed, 1,
            "the self-recursive forced operator branch must fire ONCE then let the re-entered \
             operand terminate minimally (`!x`), instead of re-forcing into a runaway `!!…`; \
             probes={:?}",
            probes
        );
        assert!(
            probes.iter().any(|p| p.matches('!').count() == 1),
            "the witnessing probe must carry exactly one operator (the bounded `!x`), proving the \
             directive fired once rather than recursively; probes={:?}",
            probes
        );
    }

    #[cfg(feature = "ebnf_dual_run")]
    #[test]
    fn plannable_witness_reaches_self_recursive_unary_operators_real_rtl_frontend() {
        // RTL-FE-CLOSURE.5.6: regression guard for the self-recursive forced-branch suppression,
        // locked on the REAL `rtl_frontend` grammar. `unary_expr := plus unary_expr | … |
        // bang unary_expr | tilde unary_expr | primary_expr` — the `bang`/`tilde` reach plans force
        // the self-recursive operator alternatives, whose operand re-enters `unary_expr`. WITHOUT
        // the .5.6 suppression the directive re-fires and the construct never yields a clean
        // operator render (the live cert-coverage failure: `bang`/`tilde` produced ZERO probe
        // samples and stayed UNKNOWN). WITH it the operand terminates minimally and the operator
        // renders exactly once. The witness check models the cert-coverage judge with a string
        // proxy (a single operator char, no runaway) so the test needs no generated parser.
        use crate::ast_pipeline::{PipelineConfig, RustASTPipeline};
        use crate::ebnf_frontend::parse_ebnf_file_to_raw_ast_envelope;

        let grammar_path = concat!(env!("CARGO_MANIFEST_DIR"), "/../grammars/rtl_frontend.ebnf");
        let envelope =
            parse_ebnf_file_to_raw_ast_envelope(grammar_path).expect("parse rtl_frontend.ebnf");
        let raw_ast: Vec<JsonValue> = envelope
            .get("raw_ast")
            .and_then(|v| v.as_array())
            .expect("envelope.raw_ast array")
            .clone();
        let (grammar_tree, rule_order, _ann) = RustASTPipeline::new(PipelineConfig::default())
            .transform_from_raw_ast(&raw_ast)
            .expect("transform_from_raw_ast");
        let mut generator = StimuliGenerator::new(
            "rtl_frontend".to_string(),
            &grammar_tree,
            &rule_order,
            None,
            StimuliConfig {
                seed: Some(0),
                ..StimuliConfig::default()
            },
        );

        let mut probes: Vec<(String, String)> = Vec::new();
        let report = generator.generate_plannable_rule_witnesses(
            "rtl_frontend_file",
            &["bang".to_string(), "tilde".to_string()],
            250,
            4,
            |rule, sample| {
                probes.push((rule.to_string(), sample.to_string()));
                let op = if rule == "bang" { '!' } else { '~' };
                // String proxy for the cert-coverage judge (which checks the parser ENTERED the
                // rule): an operator-bearing valid sample witnesses. The discriminator is whether a
                // sample is produced AT ALL — on the real grammar the un-fixed self-recursion never
                // terminates the operand, so `bang`/`tilde` produce ZERO probe samples (the live
                // cert-coverage failure); the fix lets the operand terminate, so the reach path
                // renders a real `… bit[ !a ? … ] …` expression carrying the operator. (Samples are
                // rich ternary range expressions, so they carry several operators — entry, not a
                // single occurrence, is what the real judge certifies.)
                if sample.contains(op) {
                    PlannableProbeVerdict::Witnessed
                } else {
                    PlannableProbeVerdict::ParsedNotWitnessed
                }
            },
        );
        assert_eq!(
            report.witnessed, 2,
            "both `bang` and `tilde` must witness via a single-operator render once the \
             self-recursive forced branch fires once and the operand terminates; probes={:?}",
            probes
        );
    }

